    for k in ks:
        tmux(["send-keys","-t",SESS,k]); time.sleep(wait)
def kill(): tmux(["kill-session","-t",SESS])
def show(label=""):
    print(f"--- {label} ---")
    print(cap())
    print("--- esc ---")
    print(repr(cap(esc=True)))
