static int cmp_int_str(const char *s) { return s ? atoi(s) : 0; }

/* Apply one option character (from the command line or NNN_OPTS).
 * Returns 0 to continue, or an exit status via *exit_now. */
static int apply_option(int opt, const char *arg, bool *exit_now)
{
    *exit_now = false;
    switch (opt) {
    case 'a': gcfg.autofifo = true; break;
    case 'A': gcfg.noautoenter = true; break;
    case 'b': free(gcfg.bookmark_key); gcfg.bookmark_key = xstrdup(arg ? arg : ""); break;
    case 'B': gcfg.bsdtar = true; break;
    case 'c': gcfg.cli_opener = true; break;
    case 'C': gcfg.color8 = true; break;
    case 'd': gcfg.detail0 = true; break;
    case 'D': gcfg.ctxcolor_dir = true; break;
    case 'e': gcfg.editor_text = true; break;
    case 'E': gcfg.editor_internal = true; break;
    case 'f': gcfg.history = true; break;
    case 'F': {
        int v = arg ? atoi(arg) : 0;
        if (arg && (v < 0 || v > 1)) { *exit_now = true; return 1; }
        gcfg.fifo_mode = v; break; }
    case 'g': gcfg.regex_filter0 = true; break;
    case 'H': gcfg.hidden0 = true; break;
    case 'i': gcfg.show_info = true; break;
    case 'J': gcfg.noadvance = true; break;
    case 'K': *exit_now = true; return 0;
    case 'l': if (arg) gcfg.scroll_lines = atol(arg); break;
    case 'n': gcfg.tty_nav0 = true; break;
    case 'N': gcfg.native_prompt = true; break;
    case 'o': gcfg.open_enter_only = true; break;
    case 'p': free(gcfg.picker_file); gcfg.picker_file = xstrdup(arg ? arg : ""); break;
    case 'P': free(gcfg.plugin_key); gcfg.plugin_key = xstrdup(arg ? arg : ""); break;
    case 'Q': gcfg.no_quit_confirm = true; break;
    case 'r': gcfg.advcp = true; break;
    case 'R': gcfg.no_rollover = true; break;
    case 's': free(gcfg.session_name); gcfg.session_name = xstrdup(arg ? arg : ""); break;
    case 'S': gcfg.persistent = true; break;
    case 't': if (arg) gcfg.lock_secs = atol(arg); break;
    case 'T': if (arg && *arg) gcfg.sort_key0 = *arg; break;
    case 'u': gcfg.use_selection = true; break;
    case 'U': gcfg.show_ug = true; break;
    case 'V': fputs("5.2\n", stdout); *exit_now = true; return 0;
    case 'x': gcfg.xflags = true; break;
    case 'z': gcfg.fuzzy0 = true; break;
    case '0': gcfg.picker_null = true; break;
    case 'h': print_usage(); *exit_now = true; return 0;
    default: break;
    }
    return 0;
}

static const char VALID_OPTS[] = "aAbBcCdDeEfFgHiJKlnNopPQrRsStTuUVxz0h";

/* ------------------------------------------------------------------ */
/* entries, sorting, filtering                                         */

typedef struct Entry {
    char *name;
    mode_t mode;        /* lstat mode */
    mode_t fmode;       /* stat() mode when symlink target exists, else mode */
    off_t size;         /* lstat size */
    off_t fsize;
    blkcnt_t blocks;
    nlink_t nlink;
    ino_t ino;
    uid_t uid; gid_t gid;
    time_t atime, mtime, ctime;
    time_t fatime, fmtime, fctime;
    unsigned long long du; /* disk/apparent usage when computed */
    bool is_dir;        /* following symlinks */
    bool is_lnk;
    bool selected;
} Entry;

enum { SORT_NAME=0, SORT_TIME, SORT_SIZE, SORT_EXT, SORT_VER };
enum { TIME_MOD=0, TIME_ACCESS, TIME_CHANGE };
enum { DETAIL_LIGHT=0, DETAIL_FULL, DETAIL_DU, DETAIL_AU };
enum { FILTER_STR=0, FILTER_FZY, FILTER_REG };

typedef struct Context {
    bool active;
    char *path;
    char *lastdir;
    char *hover;        /* name to restore cursor to */
    int cur;
    int off;
    int sort;
    bool reverse;
    int timetype;
    int detail;
    bool hidden;
    bool tty_nav;
    /* filter state */
    char *filter;       /* current prompt buffer / applied pattern */
    char *lastfilter;
    int ftype;
    bool icase;
    bool filtered;      /* a filter is applied to the listing */
    Entry **base;       /* entries the next filter applies to */
    int nbase;
    /* range selection anchor (-1 none), as an index in the view
     * captured by name */
    char *range_anchor;
    /* list directory owned by this context (stdin/plugin list) */
    char *listdir;
} Context;

static Context ctxs[MAX_CTX];
static int curctx = 0;
static Entry *entries = NULL;   /* all entries of current dir (owned by cur ctx load) */
static int nentries = 0, capentries = 0;
static Entry **view = NULL;
static int nview = 0, capview = 0;
static char *pending_create = NULL;  /* prefilled name for create prompt at start */
static char *startup_msg = NULL;

static Context *CTX(void) { return &ctxs[curctx]; }

static char *entry_path(const Entry *e)
{
    return join_path(CTX()->path, e->name);
}
static const char *entry_ext(const Entry *e)
{
    const char *d = strrchr(e->name, '.');
    if (!d || d == e->name) return "";
    return d + 1;
}
static time_t entry_time(const Entry *e, int tt)
{
    /* Displayed/sort time uses the target's times for valid symlinks. */
    if (tt == TIME_ACCESS) return e->is_lnk ? e->fatime : e->atime;
    if (tt == TIME_CHANGE) return e->is_lnk ? e->fctime : e->ctime;
    return e->is_lnk ? e->fmtime : e->mtime;
}
static bool entry_young(const Entry *e)
{
    time_t now = time(NULL);
    time_t ct = e->ctime;
    return ct <= now && (now - ct) < YOUNG_SECS;
}

/* --- name comparison --- */
static bool all_digits_prefix(const char *s, long *val)
{
    if (!isdigit((unsigned char)*s)) return false;
    char *end; *val = strtol(s, &end, 10);
    return end != s;
}
static int name_cmp_default(const char *a, const char *b)
{
    long va = 0, vb = 0;
    if (all_digits_prefix(a, &va) && all_digits_prefix(b, &vb)) {
        /* Only when both names begin with a digit: compare that leading
         * number first (gives numeric order in /proc etc.), then names. */
        if (va != vb) return va < vb ? -1 : 1;
    }
    int r = strcmp(a, b);
    return r < 0 ? -1 : (r > 0 ? 1 : 0);
}
static int ci_cmp(const char *a, const char *b)
{
    int r = strcasecmp(a, b);
    return r < 0 ? -1 : (r > 0 ? 1 : 0);
}
/* Version (natural) comparison, case insensitive.  Numeric runs compare
 * by value; runs with leading zeroes sort before the same value without. */
static int ver_cmp(const char *a, const char *b)
{
    const unsigned char *x = (const unsigned char*)a, *y = (const unsigned char*)b;
    while (*x || *y) {
        if (isdigit(*x) && isdigit(*y)) {
            const unsigned char *x0 = x, *y0 = y;
            while (*x == '0') x++;
            while (*y == '0') y++;
            const unsigned char *xe = x, *ye = y;
            while (isdigit(*xe)) xe++;
            while (isdigit(*ye)) ye++;
            long lx = xe - x, ly = ye - y;
            if (lx != ly) return lx < ly ? -1 : 1;
            int r = strncmp((const char*)x, (const char*)y, (size_t)lx);
            if (r) return r < 0 ? -1 : 1;
            long zx = x - x0, zy = y - y0;
            if (zx != zy) return zx > zy ? -1 : 1; /* more leading zeros first */
            x = xe; y = ye;
        } else {
            int ca = tolower(*x), cb = tolower(*y);
            if (ca != cb) return ca < cb ? -1 : 1;
            if (*x) x++; if (*y) y++;
        }
    }
    return 0;
}

static int entry_cmp(const void *pa, const void *pb)
{
    const Entry *a = pa, *b = pb;
    Context *c = CTX();
    if (a->is_dir != b->is_dir) return a->is_dir ? -1 : 1;
    int r = 0;
    switch (c->sort) {
    case SORT_TIME: {
        time_t ta = entry_time(a, c->timetype), tb = entry_time(b, c->timetype);
        r = (ta > tb) ? -1 : (ta < tb ? 1 : 0);
        break; }
    case SORT_SIZE: {
        unsigned long long sa = (c->detail >= DETAIL_DU) ? a->du : (unsigned long long)a->size;
        unsigned long long sb = (c->detail >= DETAIL_DU) ? b->du : (unsigned long long)b->size;
        r = (sa > sb) ? -1 : (sa < sb ? 1 : 0);
        break; }
    case SORT_EXT: {
        r = ci_cmp(entry_ext(a), entry_ext(b));
        break; }
    case SORT_VER:
        r = ver_cmp(a->name, b->name);
        break;
    default: break;
    }
    if (!r) {
        if (c->sort == SORT_VER) r = ver_cmp(a->name, b->name);
        if (!r) r = name_cmp_default(a->name, b->name);
    }
    if (c->reverse) r = -r;
    return r;
}
static int entry_ptr_cmp(const void *pa, const void *pb)
{
    const Entry *a = *(Entry *const*)pa, *b = *(Entry *const*)pb;
    return entry_cmp(a, b);
}

/* fuzzy subsequence match */
static bool fuzzy_match(const char *name, const char *pat, bool icase)
{
    while (*pat) {
        if (!*name) return false;
        int a = icase ? tolower((unsigned char)*name) : (unsigned char)*name;
        int b = icase ? tolower((unsigned char)*pat) : (unsigned char)*pat;
        if (a == b) pat++;
        name++;
    }
    return true;
}
static bool plain_match(const char *name, const char *pat, bool icase)
{
    if (!icase) return strstr(name, pat) != NULL;
    size_t lp = strlen(pat), ln = strlen(name);
    if (!lp) return true;
    for (size_t i = 0; i + lp <= ln; i++)
        if (!strncasecmp(name + i, pat, lp)) return true;
    return false;
}
static bool entry_matches(const Entry *e, const char *pat, int ftype, bool icase, regex_t *re)
{
    if (!pat || !*pat) return true;
    if (ftype == FILTER_FZY) return fuzzy_match(e->name, pat, icase);
    if (ftype == FILTER_REG) {
        if (!re) return false;
        return regexec(re, e->name, 0, NULL, 0) == 0;
    }
    return plain_match(e->name, pat, icase);
}

/* Rebuild the view from CTX()->base using the context filter. */
static void rebuild_view(void)
{
    Context *c = CTX();
    regex_t re; regex_t *rep = NULL;
    if (c->ftype == FILTER_REG && c->filter && *c->filter) {
        if (regcomp(&re, c->filter, REG_EXTENDED | REG_NOSUB | (c->icase ? REG_ICASE : 0)) == 0)
            rep = &re;
    }
    nview = 0;
    for (int i = 0; i < c->nbase; i++) {
        Entry *e = c->base[i];
        if (entry_matches(e, c->filter, c->ftype, c->icase, rep)) {
            if (nview == capview) { capview = capview ? capview * 2 : 64; view = xrealloc(view, (size_t)capview * sizeof *view); }
            view[nview++] = e;
        }
    }
    if (rep) regfree(rep);
    if (c->cur >= nview) c->cur = nview ? nview - 1 : 0;
    if (c->cur < 0) c->cur = 0;
}
static void set_base_to_all(void)
{
    Context *c = CTX();
    free(c->base);
    c->base = xmalloc(sizeof(Entry*) * (size_t)(nentries ? nentries : 1));
    c->nbase = nentries;
    for (int i = 0; i < nentries; i++) c->base[i] = &entries[i];
}
static void set_base_to_view(void)
{
    Context *c = CTX();
    free(c->base);
    c->base = xmalloc(sizeof(Entry*) * (size_t)(nview ? nview : 1));
    c->nbase = nview;
    for (int i = 0; i < nview; i++) c->base[i] = view[i];
}

static Entry *cur_entry(void)
{
    if (!nview || CTX()->cur < 0 || CTX()->cur >= nview) return NULL;
    return view[CTX()->cur];
}
static int find_in_view(const char *name)
{
    for (int i = 0; i < nview; i++) if (!strcmp(view[i]->name, name)) return i;
    return -1;
}

static void free_entries(void)
{
    for (int i = 0; i < nentries; i++) free(entries[i].name);
    free(entries); entries = NULL; nentries = capentries = 0;
    nview = 0;
    free(CTX()->base); CTX()->base = NULL; CTX()->nbase = 0;
}

/* ------------------------------------------------------------------ */
/* selection                                                           */

static char **sel = NULL;
static int nsel = 0, capsel = 0;
static void sel_write_file(void);
static int sel_index(const char *path)
{
    for (int i = 0; i < nsel; i++) if (!strcmp(sel[i], path)) return i;
    return -1;
}
static void sel_add(const char *path)
{
    if (sel_index(path) >= 0) return;
    if (nsel == capsel) { capsel = capsel ? capsel * 2 : 16; sel = xrealloc(sel, (size_t)capsel * sizeof *sel); }
    sel[nsel++] = xstrdup(path);
}
static void sel_remove_at(int i)
{
    free(sel[i]);
    memmove(&sel[i], &sel[i + 1], (size_t)(nsel - i - 1) * sizeof *sel);
    nsel--;
}
static void sel_clear(bool write)
{
    freev(sel, nsel); sel = NULL; nsel = capsel = 0;
    for (int i = 0; i < nentries; i++) entries[i].selected = false;
    if (write) sel_write_file();
}
static void sel_sync_flags(void)
{
    for (int i = 0; i < nentries; i++) {
        char *p = join_path(CTX()->path, entries[i].name);
        entries[i].selected = sel_index(p) >= 0;
        free(p);
    }
}
static void sel_write_file(void)
{
    if (!G.selpath) return;
    if (gcfg.picker_file && !strcmp(gcfg.picker_file, "-")) return;
    FILE *f = fopen(G.selpath, "wb");
    if (!f) return;
    for (int i = 0; i < nsel; i++) {
        if (i) fputc('\0', f);
        fputs(sel[i], f);
    }
    fclose(f);
}
/* Paths from the on-disk selection file (used by cp/mv/etc. when this
 * instance itself has nothing selected). */
static char **sel_from_file(int *outn)
{
    *outn = 0;
    if (!G.selpath) return NULL;
    if (gcfg.picker_file && !strcmp(gcfg.picker_file, "-")) return NULL;
    FILE *f = fopen(G.selpath, "rb");
    if (!f) return NULL;
    size_t cap = 4096, len = 0; char *buf = xmalloc(cap);
    size_t r;
    while ((r = fread(buf + len, 1, cap - len, f)) > 0) {
        len += r;
        if (len == cap) { cap *= 2; buf = xrealloc(buf, cap); }
    }
    fclose(f);
    if (!len) { free(buf); return NULL; }
    char **v = NULL; int n = 0, c2 = 0;
    size_t start = 0;
    for (size_t i = 0; i <= len; i++) {
        if (i == len || buf[i] == '\0') {
            if (i > start) {
                if (n == c2) { c2 = c2 ? c2 * 2 : 8; v = xrealloc(v, (size_t)c2 * sizeof *v); }
                v[n++] = xstrndup(buf + start, i - start);
            }
            start = i + 1;
        }
    }
    free(buf);
    *outn = n;
    return v;
}
/* Effective selection for file operations.  The returned array is either
 * the internal selection (borrowed, *borrowed=1) or a fresh list. */
static char **effective_selection(int *outn, bool *borrowed)
{
    *borrowed = false;
    if (nsel) { *outn = nsel; *borrowed = true; return sel; }
    return sel_from_file(outn);
}
EOF
wc -l nnn.c"}

