{
    *exit_now = false;
    switch (opt) {
    case 'a': gcfg.autofifo = true; break;
    case 'A': gcfg.noautoenter = true; break;
    case 'b': free(gcfg.bookmark_key); gcfg.bookmark_key = xstrdup(arg ? arg : ""); break;
