    char *lastfilter;
    int ftype;
    bool icase;
    bool filtered;      /* a filter is applied to the listing */
    Entry **base;       /* entries the next filter applies to */
    int nbase;
    /* range selection anchor (-1 none), as an index in the view
     * captured by name */
    char *range_anchor;
    /* list directory owned by this context (stdin/plugin list) */
