}
static void *xrealloc(void *p, size_t n)
{
    void *q = realloc(p, n ? n : 1);
    if (!q) { perror("realloc"); exit(1); }
    return q;
}
static char *xstrdup(const char *s)
{
    if (!s) return NULL;
    char *p = strdup(s);
    if (!p) { perror("strdup"); exit(1); }
    return p;
}
static char *xstrndup(const char *s, size_t n)
{
    char *p = xmalloc(n + 1);
    memcpy(p, s, n); p[n] = 0; return p;
}
static void freev(char **v, int n)
{
    if (!v) return;
    for (int i = 0; i < n; i++) free(v[i]);
    free(v);
}

static const char *base_name(const char *path)
{
    const char *s = strrchr(path, '/');
    return s ? s + 1 : path;
}
static char *dir_name_dup(const char *path)
{
    const char *s = strrchr(path, '/');
    if (!s) return xstrdup(".");
    if (s == path) return xstrdup("/");
    return xstrndup(path, (size_t)(s - path));
}
static char *join_path(const char *dir, const char *name)
{
    size_t dl = strlen(dir), nl = strlen(name);
    int slash = (dl && dir[dl - 1] != '/') ? 1 : 0;
    char *p = xmalloc(dl + slash + nl + 1);
    memcpy(p, dir, dl);
    if (slash) p[dl++] = '/';
    memcpy(p + dl, name, nl + 1);
    return p;
}
static bool is_abs_path(const char *p) { return p && p[0] == '/'; }

/* Make an absolute, normalised copy of path (resolving "." and ".."
 * lexically, then with realpath() when the target exists). */
static char *abs_path(const char *path)
{
    if (!path || !*path) path = ".";
    char *full;
    if (is_abs_path(path)) {
        full = xstrdup(path);
    } else {
        char cwd[PATH_MAX];
        if (!getcwd(cwd, sizeof cwd)) return xstrdup(path);
        full = join_path(cwd, path);
    }
    char *rp = realpath(full, NULL);
    if (rp) { free(full); return rp; }
    /* Lexical normalisation for a path which may not exist yet. */
    char *copy = full;
    char **parts = NULL; int n = 0, cap = 0;
    char *save = NULL;
    for (char *tok = strtok_r(copy, "/", &save); tok; tok = strtok_r(NULL, "/", &save)) {
        if (!strcmp(tok, ".")) continue;
        if (!strcmp(tok, "..")) { if (n) n--; continue; }
        if (n == cap) { cap = cap ? cap * 2 : 16; parts = xrealloc(parts, (size_t)cap * sizeof *parts); }
        parts[n++] = tok;
    }
    size_t len = 2;
    for (int i = 0; i < n; i++) len += strlen(parts[i]) + 1;
    char *out = xmalloc(len); out[0] = 0;
    if (!n) strcpy(out, "/");
    for (int i = 0; i < n; i++) { strcat(out, "/"); strcat(out, parts[i]); }
    free(parts); free(full);
    return out;
}

static int mkdir_p(const char *path)
{
    if (!path || !*path) return -1;
    char *tmp = xstrdup(path);
    size_t len = strlen(tmp);
    while (len > 1 && tmp[len - 1] == '/') tmp[--len] = 0;
    for (char *p = tmp + 1; *p; p++) {
        if (*p == '/') {
            *p = 0;
            if (mkdir(tmp, 0755) && errno != EEXIST) { int e = errno; free(tmp); errno = e; return -1; }
            *p = '/';
        }
    }
    int rc = mkdir(tmp, 0755);
    int e = errno;
    free(tmp);
    if (rc && e != EEXIST) { errno = e; return -1; }
    return 0;
}

/* Human readable size, e.g. 37B, 1.5K, 1.43M (integer arithmetic). */
static void human_size(unsigned long long size, char *buf, size_t bufsz)
{
    static const char units[] = "BKMGTPE";
    int exp = 0;
    unsigned long long div = 1;
    while (exp < 6 && size >= div * 1024ULL) { div *= 1024ULL; exp++; }
    if (!exp) { snprintf(buf, bufsz, "%llu%c", size, units[0]); return; }
    unsigned long long scale = 1;
    for (int i = 0; i < exp; i++) scale *= 10ULL;
    __int128 num = (__int128)size * scale;
    unsigned long long scaled = (unsigned long long)((num + div / 2) / div);
    unsigned long long ip = scaled / scale, fp = scaled % scale;
    if (!fp) snprintf(buf, bufsz, "%llu%c", ip, units[exp]);
    else snprintf(buf, bufsz, "%llu.%0*llu%c", ip, exp, fp, units[exp]);
}

static void mode_string(mode_t mode, mode_t permmode, char out[11])
{
    static const char rwx[] = "rwxrwxrwx";
    char type = '?';
    if (S_ISDIR(mode)) type = 'd';
    else if (S_ISLNK(mode)) type = 'l';
    else if (S_ISFIFO(mode)) type = 'p';
    else if (S_ISSOCK(mode)) type = 's';
    else if (S_ISCHR(mode)) type = 'c';
    else if (S_ISBLK(mode)) type = 'b';
    else if (S_ISREG(mode)) type = '-';
    out[0] = type;
    mode_t m = permmode;
    for (int i = 0; i < 9; i++) out[1 + i] = (m & (1ULL << (8 - i))) ? rwx[i] : '-';
    if (m & S_ISUID) out[3] = (m & S_IXUSR) ? 's' : 'S';
    if (m & S_ISGID) out[6] = (m & S_IXGRP) ? 's' : 'S';
    if (m & S_ISVTX) out[9] = (m & S_IXOTH) ? 't' : 'T';
    out[10] = 0;
}

static bool has_suffix_ci(const char *s, const char *suf)
{
    size_t ls = strlen(s), lf = strlen(suf);
    if (ls < lf) return false;
    return strcasecmp(s + ls - lf, suf) == 0;
}

