static const char *entry_ext(const Entry *e)
{
    const char *d = strrchr(e->name, '.');
    if (!d || d == e->name) return "";
    return d + 1;
}
static time_t entry_time(const Entry *e, int tt)
{
    /* Displayed/sort time uses the target's times for valid symlinks. */
    if (tt == TIME_ACCESS) return e->is_lnk ? e->fatime : e->atime;
    if (tt == TIME_CHANGE) return e->is_lnk ? e->fctime : e->ctime;
    return e->is_lnk ? e->fmtime : e->mtime;
}
static bool entry_young(const Entry *e)
{
    time_t now = time(NULL);
    time_t ct = e->ctime;
    return ct <= now && (now - ct) < YOUNG_SECS;
}

/* --- name comparison --- */
static bool all_digits_prefix(const char *s, long *val)
{
    if (!isdigit((unsigned char)*s)) return false;
    char *end; *val = strtol(s, &end, 10);
    return end != s;
}
static int name_cmp_default(const char *a, const char *b)
{
    long va = 0, vb = 0;
    if (all_digits_prefix(a, &va) && all_digits_prefix(b, &vb)) {
        /* Only when both names begin with a digit: compare that leading
         * number first (gives numeric order in /proc etc.), then names. */
        if (va != vb) return va < vb ? -1 : 1;
    }
    int r = strcmp(a, b);
    return r < 0 ? -1 : (r > 0 ? 1 : 0);
}
static int ci_cmp(const char *a, const char *b)
{
    int r = strcasecmp(a, b);
    return r < 0 ? -1 : (r > 0 ? 1 : 0);
}
/* Version (natural) comparison, case insensitive.  Numeric runs compare
 * by value; runs with leading zeroes sort before the same value without. */
static int ver_cmp(const char *a, const char *b)
{
    const unsigned char *x = (const unsigned char*)a, *y = (const unsigned char*)b;
    while (*x || *y) {
        if (isdigit(*x) && isdigit(*y)) {
            const unsigned char *x0 = x, *y0 = y;
            while (*x == '0') x++;
            while (*y == '0') y++;
            const unsigned char *xe = x, *ye = y;
            while (isdigit(*xe)) xe++;
            while (isdigit(*ye)) ye++;
            long lx = xe - x, ly = ye - y;
            if (lx != ly) return lx < ly ? -1 : 1;
            int r = strncmp((const char*)x, (const char*)y, (size_t)lx);
            if (r) return r < 0 ? -1 : 1;
            long zx = x - x0, zy = y - y0;
            if (zx != zy) return zx > zy ? -1 : 1; /* more leading zeros first */
            x = xe; y = ye;
        } else {
            int ca = tolower(*x), cb = tolower(*y);
            if (ca != cb) return ca < cb ? -1 : 1;
            if (*x) x++; if (*y) y++;
        }
    }
    return 0;
}

static int entry_cmp(const void *pa, const void *pb)
{
    const Entry *a = pa, *b = pb;
    Context *c = CTX();
    if (a->is_dir != b->is_dir) return a->is_dir ? -1 : 1;
    int r = 0;
    switch (c->sort) {
    case SORT_TIME: {
        time_t ta = entry_time(a, c->timetype), tb = entry_time(b, c->timetype);
        r = (ta > tb) ? -1 : (ta < tb ? 1 : 0);
        break; }
    case SORT_SIZE: {
        unsigned long long sa = (c->detail >= DETAIL_DU) ? a->du : (unsigned long long)a->size;
        unsigned long long sb = (c->detail >= DETAIL_DU) ? b->du : (unsigned long long)b->size;
        r = (sa > sb) ? -1 : (sa < sb ? 1 : 0);
        break; }
    case SORT_EXT: {
        r = ci_cmp(entry_ext(a), entry_ext(b));
        break; }
    case SORT_VER:
        r = ver_cmp(a->name, b->name);
        break;
    default: break;
    }
    if (!r) {
        if (c->sort == SORT_VER) r = ver_cmp(a->name, b->name);
        if (!r) r = name_cmp_default(a->name, b->name);
    }
    if (c->reverse) r = -r;
    return r;
}
static int entry_ptr_cmp(const void *pa, const void *pb)
{
    const Entry *a = *(Entry *const*)pa, *b = *(Entry *const*)pb;
    return entry_cmp(a, b);
}

/* fuzzy subsequence match */
static bool fuzzy_match(const char *name, const char *pat, bool icase)
{
    while (*pat) {
        if (!*name) return false;
        int a = icase ? tolower((unsigned char)*name) : (unsigned char)*name;
        int b = icase ? tolower((unsigned char)*pat) : (unsigned char)*pat;
        if (a == b) pat++;
        name++;
    }
    return true;
}
static bool plain_match(const char *name, const char *pat, bool icase)
{
    if (!icase) return strstr(name, pat) != NULL;
    size_t lp = strlen(pat), ln = strlen(name);
    if (!lp) return true;
    for (size_t i = 0; i + lp <= ln; i++)
        if (!strncasecmp(name + i, pat, lp)) return true;
    return false;
}
static bool entry_matches(const Entry *e, const char *pat, int ftype, bool icase, regex_t *re)
{
    if (!pat || !*pat) return true;
    if (ftype == FILTER_FZY) return fuzzy_match(e->name, pat, icase);
    if (ftype == FILTER_REG) {
        if (!re) return false;
        return regexec(re, e->name, 0, NULL, 0) == 0;
    }
    return plain_match(e->name, pat, icase);
}

/* Rebuild the view from CTX()->base using the context filter. */
static void rebuild_view(void)
{
    Context *c = CTX();
    regex_t re; regex_t *rep = NULL;
    if (c->ftype == FILTER_REG && c->filter && *c->filter) {
        if (regcomp(&re, c->filter, REG_EXTENDED | REG_NOSUB | (c->icase ? REG_ICASE : 0)) == 0)
            rep = &re;
    }
    nview = 0;
    for (int i = 0; i < c->nbase; i++) {
        Entry *e = c->base[i];
        if (entry_matches(e, c->filter, c->ftype, c->icase, rep)) {
            if (nview == capview) { capview = capview ? capview * 2 : 64; view = xrealloc(view, (size_t)capview * sizeof *view); }
            view[nview++] = e;
        }
    }
    if (rep) regfree(rep);
    if (c->cur >= nview) c->cur = nview ? nview - 1 : 0;
    if (c->cur < 0) c->cur = 0;
}
static void set_base_to_all(void)
{
    Context *c = CTX();
    free(c->base);
    c->base = xmalloc(sizeof(Entry*) * (size_t)(nentries ? nentries : 1));
    c->nbase = nentries;
    for (int i = 0; i < nentries; i++) c->base[i] = &entries[i];
}
static void set_base_to_view(void)
{
    Context *c = CTX();
    free(c->base);
    c->base = xmalloc(sizeof(Entry*) * (size_t)(nview ? nview : 1));
    c->nbase = nview;
    for (int i = 0; i < nview; i++) c->base[i] = view[i];
}

static Entry *cur_entry(void)
{
    if (!nview || CTX()->cur < 0 || CTX()->cur >= nview) return NULL;
    return view[CTX()->cur];
}
static int find_in_view(const char *name)
{
    for (int i = 0; i < nview; i++) if (!strcmp(view[i]->name, name)) return i;
    return -1;
}

static void free_entries(void)
{
    for (int i = 0; i < nentries; i++) free(entries[i].name);
    free(entries); entries = NULL; nentries = capentries = 0;
    nview = 0;
    free(CTX()->base); CTX()->base = NULL; CTX()->nbase = 0;
}

/* ------------------------------------------------------------------ */
/* selection                                                           */

static char **sel = NULL;
static int nsel = 0, capsel = 0;
static void sel_write_file(void);
static int sel_index(const char *path)
{
    for (int i = 0; i < nsel; i++) if (!strcmp(sel[i], path)) return i;
    return -1;
}
static void sel_add(const char *path)
{
    if (sel_index(path) >= 0) return;
    if (nsel == capsel) { capsel = capsel ? capsel * 2 : 16; sel = xrealloc(sel, (size_t)capsel * sizeof *sel); }
    sel[nsel++] = xstrdup(path);
}
static void sel_remove_at(int i)
{
    free(sel[i]);
    memmove(&sel[i], &sel[i + 1], (size_t)(nsel - i - 1) * sizeof *sel);
    nsel--;
}
static void sel_clear(bool write)
{
    freev(sel, nsel); sel = NULL; nsel = capsel = 0;
    for (int i = 0; i < nentries; i++) entries[i].selected = false;
    if (write) sel_write_file();
}
static void sel_sync_flags(void)
{
    for (int i = 0; i < nentries; i++) {
        char *p = join_path(CTX()->path, entries[i].name);
        entries[i].selected = sel_index(p) >= 0;
        free(p);
    }
}
static void sel_write_file(void)
{
    if (!G.selpath) return;
    if (gcfg.picker_file && !strcmp(gcfg.picker_file, "-")) return;
    FILE *f = fopen(G.selpath, "wb");
    if (!f) return;
    for (int i = 0; i < nsel; i++) {
        if (i) fputc('\0', f);
