/* ------------------------------------------------------------------ */
/* directory loading / disk usage                                       */

static long du_files = 0;
static unsigned long long du_total = 0;
static int inotify_fd = -1, inotify_wd = -1;

static unsigned long long entry_du_compute(const char *path, bool apparent, long *files)
{
    char *argv[] = { (char*)path, NULL };
    FTS *fts = fts_open(argv, FTS_PHYSICAL | FTS_NOCHDIR, NULL);
    unsigned long long total = 0;
    if (!fts) return 0;
    FTSENT *ent;
    while ((ent = fts_read(fts)) != NULL) {
        if (ent->fts_info == FTS_ERR || ent->fts_info == FTS_NS) continue;
        (*files)++;
        if (ent->fts_info == FTS_DP) continue; /* directory, post-order */
        if (ent->fts_statp) {
            if (apparent) total += (unsigned long long)ent->fts_statp->st_size;
            else total += (unsigned long long)ent->fts_statp->st_blocks * 512ULL;
        }
    }
    fts_close(fts);
    return total;
}

static void watch_dir(const char *path)
{
#ifdef __linux__
    if (inotify_fd < 0) inotify_fd = inotify_init1(IN_NONBLOCK | IN_CLOEXEC);
    if (inotify_fd >= 0) {
        if (inotify_wd >= 0) inotify_rm_watch(inotify_fd, inotify_wd);
        inotify_wd = inotify_add_watch(inotify_fd, path,
            IN_CREATE | IN_DELETE | IN_MOVED_FROM | IN_MOVED_TO |
            IN_MODIFY | IN_ATTRIB | IN_DELETE_SELF | IN_MOVE_SELF);
    }
#else
    (void)path;
#endif
}

/* Load CTX()->path.  hover (if non-NULL) is the entry name to land on.
 * On failure returns false and leaves the previous listing alone. */
static bool load_dir(const char *hover)
{
    Context *c = CTX();
    DIR *d = opendir(c->path);
    if (!d) return false;
    /* Remember cursor target. */
    char *want = NULL;
    if (hover) want = xstrdup(hover);
    else if (cur_entry()) want = xstrdup(cur_entry()->name);
    int oldcur = c->cur;
    free_entries();
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        if (de->d_name[0] == '.' && (!de->d_name[1] || (de->d_name[1] == '.' && !de->d_name[2])))
            continue;
        if (!c->hidden && de->d_name[0] == '.') continue;
        char *p = join_path(c->path, de->d_name);
        struct stat st, fst;
        if (lstat(p, &st)) { free(p); continue; }
        bool islnk = S_ISLNK(st.st_mode);
        if (islnk) {
            if (stat(p, &fst)) fst = st;
        } else fst = st;
        free(p);
        if (nentries == capentries) {
            capentries = capentries ? capentries * 2 : 128;
            entries = xrealloc(entries, (size_t)capentries * sizeof(Entry));
        }
        Entry *e = &entries[nentries++];
        memset(e, 0, sizeof *e);
        e->name = xstrdup(de->d_name);
        e->mode = st.st_mode;
        e->fmode = fst.st_mode;
        e->size = st.st_size; e->fsize = fst.st_size;
        e->blocks = st.st_blocks; e->nlink = st.st_nlink; e->ino = st.st_ino;
        e->uid = st.st_uid; e->gid = st.st_gid;
        e->atime = st.st_atime; e->mtime = st.st_mtime; e->ctime = st.st_ctime;
        e->fatime = fst.st_atime; e->fmtime = fst.st_mtime; e->fctime = fst.st_ctime;
        e->is_lnk = islnk;
        e->is_dir = S_ISDIR(fst.st_mode);
    }
    closedir(d);
    /* Disk usage for DU modes. */
    du_files = 0; du_total = 0;
    if (c->detail >= DETAIL_DU) {
        bool apparent = (c->detail == DETAIL_AU);
        for (int i = 0; i < nentries; i++) {
            char *p = join_path(c->path, entries[i].name);
            long files = 0;
            entries[i].du = entry_du_compute(p, apparent, &files);
            du_files += files;
            du_total += entries[i].du;
            free(p);
        }
    }
    if (nentries > 1) qsort(entries, (size_t)nentries, sizeof(Entry), entry_cmp);
    sel_sync_flags();
    set_base_to_all();
    if (c->filtered && c->filter && *c->filter) {
        rebuild_view();
    } else {
        /* plain listing */
        if (c->filter) c->filter[0] = 0;
        c->filtered = false;
        rebuild_view();
    }
    c->cur = oldcur;
    if (want) {
        int idx = find_in_view(want);
        if (idx >= 0) c->cur = idx;
        free(want);
    }
    if (c->cur >= nview) c->cur = nview ? nview - 1 : 0;
    if (c->cur < 0) c->cur = 0;
    c->off = 0;
    (void)chdir(c->path);
    watch_dir(c->path);
    return true;
}

/* Change the current context to (absolute) dir; on failure set the
 * status message and keep the old directory. */
static char *g_msg = NULL;
static bool g_msg_ised = false; rout_placeholder_unused:
static void set_msg(const char *s);
static bool change_dir_abs(char *absdir, const char *hover)
{
    Context *c = CTX();
    char *oldpath = c->path;
    char *oldlast = c->lastdir;
    (void)oldlast;
    c->path = absdir;
    /* dir change resets any filter */
    if (c->filter) { free(c->lastfilter); c->lastfilter = xstrdup(c->filter); }
    free(c->filter); c->filter = xstrdup("");
    c->filtered = false;
    if (!load_dir(hover)) {
        int e = errno;
        free(c->path); c->path = oldpath;
        /* Reload old listing if it was freed by a failed load attempt is
         * unnecessary: load_dir() bails before freeing on opendir error.
         * Restore view state from the entries still in memory. */
        set_base_to_all();
        rebuild_view();
        errno = e;
        set_msg(strerror(e ? e : EACCES));
        return false;
    }
    if (strcmp(oldpath, absdir)) {
        free(c->lastdir);
        c->lastdir = oldpath;
    } else {
        free(oldpath);
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* messages, prompts, terminal helpers                                  */

static void set_msg(const char *s)
{
    free(g_msg);
    g_msg = s ? xstrdup(s) : NULL;
    (void)g_msg_ised;
}
static void set_errmsg(void) { set_msg(strerror(errno)); }

static void draw(void);
static int get_key(int *mod_escape_pending);
static void suspend_curses(void)
{
    def_prog_mode();
    endwin();
}
static void resume_curses(void)
{
    reset_prog_mode();
    refresh();
}

/* Read a line from the terminal after an external command, used for
 * the "'Enter' to continue" pause. */
static void wait_enter(void)
{
    fputs("'Enter' to continue", stdout);
    fflush(stdout);
    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF) { }
}

static bool g_exiting = false;

/* Fork/exec a program (argv, NULL terminated).  If shell is non-NULL the
 * string is run with "$SHELL -c" (or /bin/sh) instead. */
static int run_external(char *const argv[], const char *shellcmd, bool wait_always, bool bg)
{
    suspend_curses();
    pid_t pid = fork();
    if (pid == 0) {
        if (shellcmd) {
            const char *sh = G.shell ? G.shell : "/bin/sh";
            execl(sh, sh, "-c", shellcmd, (char*)NULL);
        } else {
            execvp(argv[0], argv);
        }
        _exit(127);
    }
    int status = 0;
    if (pid > 0 && !bg) {
        while (waitpid(pid, &status, 0) < 0 && errno == EINTR) { }
    }
    if (!bg && (wait_always || (pid > 0 && (!WIFEXITED(status) || WEXITSTATUS(status) != 0)))) {
        if (!(wait_always && shellcmd) )
            wait_enter();
    }
    resume_curses();
    return (pid > 0 && WIFEXITED(status)) ? WEXITSTATUS(status) : 1;
}
