/* ------------------------------------------------------------------ */
/* colours / rendering                                                  */

enum {
    PAIR_CTX = 1,           /* 1..8 */
    PAIR_META = 9,
    PAIR_BLK, PAIR_CHR, PAIR_DIR, PAIR_EXE, PAIR_REG, PAIR_HARD,
    PAIR_LINK, PAIR_MISSING, PAIR_ORPHAN, PAIR_FIFO, PAIR_SOCK, PAIR_EMPTY
};
static int fcolors[12] = { 220, 226, 39, 46, -1, 96, 51, 255, 198, 214, 171, 196 };

static void parse_fcolors(void)
{
    const char *s = getenv("NNN_FCOLORS");
    if (!s) return;
    for (int i = 0; i < 12; i++) {
        if (!s[2*i] || !s[2*i+1]) break;
        char tmp[3] = { s[2*i], s[2*i+1], 0 };
        char *end; long v = strtol(tmp, &end, 16);
        if (end != tmp) fcolors[i] = (v == 0) ? -1 : (int)v;
    }
}
static bool col256(void) { return G.colors_on && !G.force_8color && COLORS >= 256; }

static void init_colours(void)
{
    if (!has_colors()) { G.colors_on = false; return; }
    start_color();
    use_default_colors();
    for (int i = 0; i < MAX_CTX; i++)
        init_pair(PAIR_CTX + i, G.colors_on ? G.ctxcolors[i] : -1, -1);
    if (!G.colors_on) {
        for (int i = PAIR_META; i <= PAIR_EMPTY; i++) init_pair(i, -1, -1);
        return;
    }
    if (col256()) {
        init_pair(PAIR_META, 247, -1);
        for (int i = 0; i < 12; i++) init_pair(PAIR_BLK + i, fcolors[i], -1);
    } else {
        init_pair(PAIR_META, -1, -1);
        init_pair(PAIR_BLK, COLOR_YELLOW, -1);
        init_pair(PAIR_CHR, COLOR_YELLOW, -1);
        init_pair(PAIR_DIR, COLOR_BLUE, -1);
        init_pair(PAIR_EXE, -1, -1);
        init_pair(PAIR_REG, -1, -1);
        init_pair(PAIR_HARD, -1, -1);
        init_pair(PAIR_LINK, -1, -1);
        init_pair(PAIR_MISSING, -1, -1);
        init_pair(PAIR_ORPHAN, -1, -1);
        init_pair(PAIR_FIFO, -1, -1);
        init_pair(PAIR_SOCK, -1, -1);
        init_pair(PAIR_EMPTY, -1, -1);
    }
}
static int ctx_pair(void) { return COLOR_PAIR(PAIR_CTX + curctx); }
static int entry_pair(const Entry *e)
{
    if (!G.colors_on) return 0;
    if (!col256()) {
        if (e->is_dir && !e->is_lnk) return COLOR_PAIR(PAIR_DIR);
        return 0;
    }
    mode_t m = e->mode;
    if (e->is_lnk) {
        struct stat st;
        char *p = entry_path(e);
        bool ok = stat(p, &st) == 0;
        free(p);
        return COLOR_PAIR(ok ? PAIR_LINK : PAIR_ORPHAN);
    }
    if (S_ISDIR(m)) {
        if (gcfg.ctxcolor_dir && getenv("NNN_COLORS")) return ctx_pair();
        if (gcfg.ctxcolor_dir) return 0;
        return COLOR_PAIR(PAIR_DIR);
    }
    if (S_ISBLK(m)) return COLOR_PAIR(PAIR_BLK);
    if (S_ISCHR(m)) return COLOR_PAIR(PAIR_CHR);
    if (S_ISFIFO(m)) return COLOR_PAIR(PAIR_FIFO);
    if (S_ISSOCK(m)) return COLOR_PAIR(PAIR_SOCK);
    if (S_ISREG(m)) {
        if (e->size == 0) return COLOR_PAIR(PAIR_EMPTY);
        if (m & (S_IXUSR | S_IXGRP | S_IXOTH)) return COLOR_PAIR(PAIR_EXE);
        if (e->nlink > 1) return COLOR_PAIR(PAIR_HARD);
        return COLOR_PAIR(PAIR_REG);
    }
    return COLOR_PAIR(PAIR_EMPTY);
}
static bool entry_bold_name(const Entry *e)
{
    if (col256() || !G.colors_on) return e->is_dir;
    return e->is_dir && !e->is_lnk;
}
static char entry_suffix(const Entry *e)
{
    if (e->is_dir) return '/';
    if (e->is_lnk) return '@';
    if (S_ISFIFO(e->mode)) return '|';
    if (S_ISSOCK(e->mode)) return '=';
    if (S_ISREG(e->mode) && (e->fmode & (S_IXUSR | S_IXGRP | S_IXOTH))) return '*';
    return 0;
}
static int strwidth(const char *s)
{
    if (!s) return 0;
    wchar_t *ws = NULL;
    size_t n = mbstowcs(NULL, s, 0);
    if (n == (size_t)-1) return (int)strlen(s);
    ws = xmalloc((n + 1) * sizeof(wchar_t));
    mbstowcs(ws, s, n + 1);
    int w = wcswidth(ws, n);
    free(ws);
    return w < 0 ? (int)strlen(s) : w;
}
/* Add a UTF-8 string truncated to at most maxcols display columns.  Any
 * control/unprintable characters are shown as '?'. */
static void addstr_trunc(const char *s, int maxcols)
{
    if (!s || maxcols <= 0) return;
    wchar_t *ws = NULL;
    size_t n = mbstowcs(NULL, s, 0);
    if (n == (size_t)-1) {
        int c = 0;
        for (const unsigned char *p = (const unsigned char*)s; *p && c < maxcols; p++, c++)
            addch(isprint(*p) ? *p : '?');
        return;
    }
    ws = xmalloc((n + 1) * sizeof(wchar_t));
    mbstowcs(ws, s, n + 1);
    int used = 0;
    for (size_t i = 0; i < n; i++) {
        wchar_t wc = ws[i];
        int w = wcwidth(wc);
        if (w < 0) { wc = L'?'; w = 1; }
        if (used + w > maxcols) break;
        addnwstr(&wc, 1);
        used += w;
    }
    free(ws);
}
static char *display_path(const char *path)
{
    if (!G.home || !*G.home) return xstrdup(path);
    size_t hl = strlen(G.home);
    if (!strcmp(path, G.home)) return xstrdup("~");
    if (!strncmp(path, G.home, hl) && path[hl] == '/') {
        char *out = xmalloc(strlen(path) - hl + 2);
        out[0] = '~'; strcpy(out + 1, path + hl);
        return out;
    }
    return xstrdup(path);
}

/* UI state shared by draw() and the prompt helpers. */
enum { UI_STATUS = 0, UI_LINE, UI_CHOICE, UI_FILTER };
static int ui_kind = UI_STATUS;
static char *ui_prompt = NULL;     /* label/prefix or full choice text */
static wchar_t *ui_input = NULL;   /* line input (wide) */
static int ui_cursor = 0;          /* cursor index in ui_input */
static bool ui_jump = false;
static bool ui_filter_prompt = false;

static int page_rows(void)
{
    int r = LINES - 4;
    return r < 1 ? 1 : r;
}
static void ensure_visible(void)
{
    Context *c = CTX();
    int pg = page_rows();
    if (c->cur < c->off) c->off = c->cur;
    if (c->cur >= c->off + pg) c->off = c->cur - pg + 1;
    int maxoff = nview > pg ? nview - pg : 0;
    if (c->off > maxoff) c->off = maxoff;
    if (c->off < 0) c->off = 0;
}

static void fmt_date(time_t t, char *buf, size_t n)
{
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, n, "%Y-%m-%d %H:%M", &tmv);
}

static void draw_entry(int row, int idx)
{
    Context *c = CTX();
    Entry *e = view[idx];
    bool iscur = (idx == c->cur);
    move(row, 0);
    int pair = entry_pair(e);
    attr_t nameattrs = 0;
    if (entry_bold_name(e)) nameattrs |= A_BOLD;
    if (!col256() && G.colors_on && e->is_lnk) nameattrs |= A_DIM;
    if (iscur) nameattrs |= A_BOLD | A_REVERSE;
    bool detail = (c->detail != DETAIL_LIGHT && COLS >= 36);
    if (ui_jump) {
        int off = idx - c->cur;
        char buf[16];
        if (off > 0) snprintf(buf, sizeof buf, "%+4d", off);
        else snprintf(buf, sizeof buf, "%4d", off);
        addstr(buf);
        addch(' ');
        if (e->selected) {
            /* offset column replaces the selection marker in light view;
             * in detail view the marker stays beside the name (below). */
            if (!detail) { /* keep offset only */ }
        }
    }
    if (detail) {
        char date[32], meta[128], sz[32];
        fmt_date(entry_time(e, c->timetype), date, sizeof date);
        if (c->detail >= DETAIL_DU) human_size(e->du, sz, sizeof sz);
        else if (e->is_lnk) strcpy(sz, "@");
        else if (S_ISFIFO(e->mode)) strcpy(sz, "|");
        else if (S_ISSOCK(e->mode)) strcpy(sz, "=");
        else if (S_ISCHR(e->mode)) strcpy(sz, "c");
        else if (S_ISBLK(e->mode)) strcpy(sz, "b");
        else human_size((unsigned long long)e->size, sz, sizeof sz);
        if (!ui_jump) {
            if (iscur) { attron(A_BOLD); addch('>'); attroff(A_BOLD); }
            else addch(' ');
        }
        snprintf(meta, sizeof meta, "  %03o %9s ", (unsigned)(e->fmode & 07777), sz);
        int metapair = G.colors_on ? COLOR_PAIR(PAIR_META) : 0;
        attr_t metaattr = 0;
        if (!col256() && G.colors_on) metaattr |= A_DIM;
        if (entry_young(e)) {
            attron(metapair | A_REVERSE | metaattr); addstr(date); attroff(metapair | A_REVERSE | metaattr);
        } else {
            attron(metapair | metaattr); addstr(date); attroff(metapair | metaattr);
        }
        attron(metapair | metaattr); addstr(meta); attroff(metapair | metaattr);
        if (e->selected) { attron(A_BOLD | A_REVERSE); addch('+'); attroff(A_BOLD | A_REVERSE); }
        else addch(' ');
        attron(pair | nameattrs);
        addstr_trunc(e->name, COLS - getcurx(stdscr) - 1);
        attroff(pair | nameattrs);
        char suf = entry_suffix(e);
        if (suf && getcurx(stdscr) < COLS - 1) addch((unsigned char)suf);
        return;
    }
    /* light view */
    if (!ui_jump) {
        if (e->selected) {
            int pp = iscur ? pair : 0;
            attron(pp | A_BOLD | A_REVERSE); addch('+'); attroff(pp | A_BOLD | A_REVERSE);
        } else addch(' ');
    }
    attron(pair | nameattrs);
    addstr_trunc(e->name, COLS - getcurx(stdscr) - 1);
    attroff(pair | nameattrs);
    char suf = entry_suffix(e);
    if (suf && getcurx(stdscr) < COLS - 1) addch((unsigned char)suf);
}

static char sort_indicators(Context *c, char *buf, size_t n)
{
    char *p = buf; (void)n;
    if (c->reverse) *p++ = 'R';
    if (c->sort == SORT_TIME) *p++ = (c->timetype == TIME_ACCESS ? 'A' : c->timetype == TIME_CHANGE ? 'C' : 'M');
    else if (c->sort == SORT_SIZE) *p++ = 'S';
    else if (c->sort == SORT_EXT) *p++ = 'E';
    /* version modifier is represented by sort==SORT_VER here; combined
     * cases are handled by the caller-visible flags below. */
    if (c->sort == SORT_VER) *p++ = 'V';
    *p = 0;
    return buf[0];
}
static void draw_status(void)
{
    Context *c = CTX();
    int row = LINES - 1;
    move(row, 0);
    attron(ctx_pair());
    if (g_msg) {
        addstr_trunc(g_msg, COLS);
        attroff(ctx_pair());
        return;
    }
    if (!nview) {
        if (ui_kind == UI_STATUS) addstr("0/0");
        attroff(ctx_pair());
        return;
    }
    Entry *e = cur_entry();
    char tmp[128];
    snprintf(tmp, sizeof tmp, "%d/%d", c->cur + 1, nview);
    addstr(tmp);
    if (c->detail >= DETAIL_DU) {
        struct statvfs sv;
        unsigned long long avail = 0;
        if (statvfs(c->path, &sv) == 0) avail = (unsigned long long)sv.f_bavail * sv.f_frsize;
        char tsz[32], asz[32];
        human_size(du_total, tsz, sizeof tsz);
        human_size(avail, asz, sizeof asz);
        snprintf(tmp, sizeof tmp, " %s:%s avail:%s files:%ld %lluB",
                 c->detail == DETAIL_AU ? "au" : "du", tsz, asz, du_files, e ? e->du : 0ULL);
        addstr_trunc(tmp, COLS - getcurx(stdscr));
        if (e && !e->is_dir && !e->is_lnk) {
            const char *ext = entry_ext(e);
            if (*ext && strlen(ext) <= 4) { addch(' '); addch('.'); addstr(ext); }
        }
        attroff(ctx_pair());
        return;
    }
    bool range_active = c->range_anchor != NULL;
    if (nsel > 0 || range_active) {
        addch(' ');
        attron(A_REVERSE);
        if (range_active && nsel > 0) snprintf(tmp, sizeof tmp, " *%d ", nsel);
        else if (range_active) snprintf(tmp, sizeof tmp, " * ");
        else snprintf(tmp, sizeof tmp, " +%d ", nsel);
        addstr(tmp);
        attroff(A_REVERSE);
    }
    /* indicator field: ' ' letters ' ' */
    addch(' ');
    char inds[16]; int ii = 0;
    if (c->hidden) inds[ii++] = 'H';
    char sbuf[8]; sort_indicators(c, sbuf, sizeof sbuf);
    for (char *p = sbuf; *p; p++) inds[ii++] = *p;
    if (c->tty_nav) inds[ii++] = 'F';
    inds[ii] = 0;
    addstr(inds);
    addch(' ');
    if (e) {
        char date[32];
        fmt_date(entry_time(e, c->timetype), date, sizeof date);
        if (entry_young(e)) attron(A_REVERSE);
        addstr(date);
        if (entry_young(e)) attroff(A_REVERSE);
        char modestr[11];
        mode_string(e->mode, e->fmode, modestr);
        addch(' '); addstr(modestr);
        if (gcfg.show_ug) {
            struct passwd *pw = getpwuid(e->uid);
            struct group *gr = getgrgid(e->gid);
            char ug[128];
            snprintf(ug, sizeof ug, " %s:%s", pw ? pw->pw_name : "?", gr ? gr->gr_name : "?");
            addstr(ug);
        }
        char sz[32]; human_size((unsigned long long)e->size, sz, sizeof sz);
        addch(' '); addstr(sz);
        if (e->is_lnk) {
            char *p = entry_path(e);
            char target[PATH_MAX];
            ssize_t r = readlink(p, target, sizeof target - 1);
            free(p);
            if (r > 0) {
                target[r] = 0;
                addstr(" ->");
                addstr_trunc(target, COLS - getcurx(stdscr));
            }
        } else {
            const char *ext = entry_ext(e);
            if (S_ISREG(e->mode) && *ext && strlen(ext) <= 4) {
                addch(' '); addch('.'); addstr(ext);
            }
            if (S_ISREG(e->mode) && e->nlink > 1) {
                snprintf(tmp, sizeof tmp, " %llu-%llu", (unsigned long long)e->nlink, (unsigned long long)e->ino);
                addstr(tmp);
            }
        }
    }
    attroff(ctx_pair());
}

static void draw(void)
{
    erase();
    Context *c = CTX();
    int pg = page_rows();
    ensure_visible();
    if (COLS >= 17) {
        /* header: contexts and path */
        move(0, 0);
        for (int i = 0; i < MAX_CTX; i++) {
            if (i) addch(' ');
            char digit = (char)('1' + i);
            if (i == curctx) {
                attron(COLOR_PAIR(PAIR_CTX + i) | A_BOLD | A_REVERSE);
                addch((unsigned char)digit);
                attroff(COLOR_PAIR(PAIR_CTX + i) | A_BOLD | A_REVERSE);
            } else if (ctxs[i].active) {
                attron(COLOR_PAIR(PAIR_CTX + i) | A_BOLD | A_UNDERLINE);
                addch((unsigned char)digit);
                attroff(COLOR_PAIR(PAIR_CTX + i) | A_BOLD | A_UNDERLINE);
            } else addch((unsigned char)digit);
        }
        addch(' ');
        char *dp = display_path(c->path);
        attron(ctx_pair() | A_UNDERLINE);
        addstr_trunc(dp, COLS - getcurx(stdscr));
        attroff(ctx_pair() | A_UNDERLINE);
        free(dp);
        if (c->off > 0) mvaddch(1, 0, '^');
        for (int i = 0; i < pg; i++) {
            int idx = c->off + i;
            if (idx >= nview) break;
            draw_entry(2 + i, idx);
        }
    }
    /* second-last row: scroll marker or filter indicator */
    int srow = LINES - 2;
    if (srow >= 0) {
        if (ui_filter_prompt) {
            const char *ft = c->ftype == FILTER_FZY ? "fzy" : c->ftype == FILTER_REG ? "reg" : "str";
            const char *ic = c->icase ? "ic" : "noic";
            char seg[64];
            snprintf(seg, sizeof seg, "  %s [/], %s [:]", ft, ic);
            int segw = strwidth(seg);
            int x = COLS - segw;
            if (c->hidden) {
                /* hidden indicator rides just before the segment */
                if (x >= 2) {
                    move(srow, x - 2);
                    attron(ctx_pair()); addch('H'); attroff(ctx_pair());
                }
            }
            if (x < 0) x = 0;
            move(srow, x);
            attron(ctx_pair());
            addstr_trunc(seg, COLS - x);
            attroff(ctx_pair());
        } else if (COLS >= 17 && c->off + pg < nview) {
            mvaddch(srow, 0, 'v');
        }
    }
    /* bottom row */
    int brow = LINES - 1;
    if (brow < 0) brow = 0;
    move(brow, 0);
    if (ui_kind == UI_LINE || ui_kind == UI_FILTER) {
        attron(ctx_pair());
        if (ui_prompt) addstr_trunc(ui_prompt, COLS);
        int used = getcurx(stdscr);
        if (ui_input) {
            char *mb = NULL;
            size_t need = wcstombs(NULL, ui_input, 0);
            if (need != (size_t)-1) {
                mb = xmalloc(need + 1); wcstombs(mb, ui_input, need + 1);
                addstr_trunc(mb, COLS - used);
                free(mb);
            }
        }
        attroff(ctx_pair());
        curs_set(1);
        int px = strwidth(ui_prompt);
        if (ui_input) {
            wchar_t save = ui_input[ui_cursor];
            ui_input[ui_cursor] = 0;
            px += wcswidth(ui_input, (size_t)ui_cursor);
            ui_input[ui_cursor] = save;
        }
        if (px >= COLS) px = COLS - 1;
        move(brow, px);
    } else if (ui_kind == UI_CHOICE) {
        attron(ctx_pair());
        if (ui_prompt) addstr_trunc(ui_prompt, COLS);
        attroff(ctx_pair());
        curs_set(0);
        int px = strwidth(ui_prompt);
        if (px >= COLS) px = COLS - 1;
        move(brow, px);
    } else {
        draw_status();
        curs_set(0);
        if (nview && COLS >= 17) {
            int crow = 2 + (c->cur - c->off);
            if (crow >= 0 && crow < LINES) move(crow, 0);
        }
    }
    refresh();
}

/* ------------------------------------------------------------------ */
/* input                                                                */

#define KEY_ALT_BASE 10000
#define KEY_ALT_ESC (KEY_ALT_BASE + 256)
#define KEY_ALT_ENTER (KEY_ALT_BASE + 257)
#define KEY_CTRL_SLASH 31

static int read_key_raw(void)
{
    wint_t ch;
    int r = get_wch(&ch);
    if (r == ERR) return ERR;
    return (int)ch;
}
/* Read one logical key.  An Escape promptly followed by another byte is
 * reported as an Alt combination. */
static int get_key(int *mod_escape_pending)
{
    (void)mod_escape_pending;
    int k = read_key_raw();
    if (k != ESC_KEY) return k;
    /* peek for a following byte */
    nodelay(stdscr, TRUE);
    int k2 = read_key_raw();
    nodelay(stdscr, FALSE);
    if (k2 == ERR) return ESC_KEY;
    if (k2 == ESC_KEY) return KEY_ALT_ESC;
    if (k2 == '\n' || k2 == '\r' || k2 == KEY_ENTER) return KEY_ALT_ENTER;
    if (k2 >= 0 && k2 < KEY_MIN) return KEY_ALT_BASE + k2;
    /* function key after ESC: push it back and report plain ESC */
    unget_wch((wchar_t)k2);
    return ESC_KEY;
}
static bool is_alt_key(int k, int ch)
{
    return k == KEY_ALT_BASE + ch;
}

/* Line input at the bottom of the screen.  Returns a malloc'd string, or
 * NULL when cancelled with Escape. */
static char *read_line(const char *prefix, const char *initial)
{
    int saved_kind = ui_kind;
    char *saved_prompt = ui_prompt;
    wchar_t *saved_input = ui_input;
    int saved_cursor = ui_cursor;
    bool saved_filter = ui_filter_prompt;
    ui_kind = UI_LINE;
    ui_prompt = xstrdup(prefix ? prefix : "");
    ui_filter_prompt = false;
    size_t cap = 64, len = 0;
    wchar_t *buf = xmalloc(cap * sizeof(wchar_t));
    buf[0] = 0;
    if (initial && *initial) {
        wchar_t wbuf[PATH_MAX];
        size_t n = mbstowcs(wbuf, initial, PATH_MAX - 1);
        if (n != (size_t)-1) {
            while (len + n + 1 > cap) { cap *= 2; buf = xrealloc(buf, cap * sizeof(wchar_t)); }
            wmemcpy(buf, wbuf, n); len = n; buf[len] = 0;
        }
    }
    ui_input = buf;
    ui_cursor = (int)len;
    char *result = NULL;
    for (;;) {
        draw();
        int k = get_key(NULL);
        if (k == ERR) continue;
        if (k == '\n' || k == '\r' || k == KEY_ENTER) {
            size_t need = wcstombs(NULL, buf, 0);
            result = xmalloc(need + 1);
            wcstombs(result, buf, need + 1);
            break;
        }
        if (k == ESC_KEY || k == KEY_ALT_ESC || k == 3) { result = NULL; break; }
        if (k == KEY_BACKSPACE || k == 127 || k == 8) {
            if (ui_cursor > 0) {
                wmemmove(&buf[ui_cursor - 1], &buf[ui_cursor], len - (size_t)ui_cursor + 1);
                ui_cursor--; len--;
            }
            continue;
        }
        if (k == KEY_DC) {
            if ((size_t)ui_cursor < len) {
                wmemmove(&buf[ui_cursor], &buf[ui_cursor + 1], len - (size_t)ui_cursor);
                len--;
            }
            continue;
        }
        if (k == KEY_LEFT) { if (ui_cursor > 0) ui_cursor--; continue; }
        if (k == KEY_RIGHT) { if ((size_t)ui_cursor < len) ui_cursor++; continue; }
        if (k == KEY_HOME || k == 1) { ui_cursor = 0; continue; }
        if (k == KEY_END || k == 5) { ui_cursor = (int)len; continue; }
        if (k == 21) { len = 0; ui_cursor = 0; buf[0] = 0; continue; }     /* ^U */
        if (k == 11) { len = (size_t)ui_cursor; buf[len] = 0; continue; }  /* ^K */
        if (k == 23) {                                                       /* ^W */
            int i = ui_cursor;
            while (i > 0 && iswspace(buf[i - 1])) i--;
            while (i > 0 && !iswspace(buf[i - 1]) && buf[i - 1] != L'/') i--;
            wmemmove(&buf[i], &buf[ui_cursor], len - (size_t)ui_cursor + 1);
            len -= (size_t)(ui_cursor - i); ui_cursor = i;
            continue;
        }
        if (k >= KEY_ALT_BASE) {
            int ak = k - KEY_ALT_BASE;
            if (ak == 127 || ak == 8) { /* Alt-Backspace: delete word */
                int i = ui_cursor;
                while (i > 0 && iswspace(buf[i - 1])) i--;
                while (i > 0 && !iswspace(buf[i - 1])) i--;
                wmemmove(&buf[i], &buf[ui_cursor], len - (size_t)ui_cursor + 1);
                len -= (size_t)(ui_cursor - i); ui_cursor = i;
            }
            continue;
        }
        if (k >= 32 && k < KEY_MIN) {
            if (len + 2 > cap) { cap *= 2; buf = xrealloc(buf, cap * sizeof(wchar_t)); ui_input = buf; }
            wmemmove(&buf[ui_cursor + 1], &buf[ui_cursor], len - (size_t)ui_cursor + 1);
            buf[ui_cursor++] = (wchar_t)k; len++;
            continue;
        }
        /* other function keys are ignored in a line prompt */
    }
    free(buf);
    free(ui_prompt);
    ui_kind = saved_kind; ui_prompt = saved_prompt; ui_input = saved_input;
    ui_cursor = saved_cursor; ui_filter_prompt = saved_filter;
    return result;
}

/* Single-key choice prompt at the bottom. */
static int read_choice(const char *prompt)
{
    int saved_kind = ui_kind;
    char *saved_prompt = ui_prompt;
    ui_kind = UI_CHOICE;
    ui_prompt = xstrdup(prompt);
    draw();
    int k;
    do { k = get_key(NULL); } while (k == ERR);
    free(ui_prompt);
    ui_kind = saved_kind; ui_prompt = saved_prompt;
    return k;
}
static bool confirm_prompt(const char *prompt)
{
    int k = read_choice(prompt);
    return k == 'y' || k == 'Y';
}
