{"command":"cat >> nnn.c <<'EOF'

/* ------------------------------------------------------------------ */
/* external programs                                                    */

static bool find_in_path(const char *name)
{
    if (!name || !*name) return false;
    if (strchr(name, '/')) return access(name, X_OK) == 0;
    const char *path = getenv("PATH");
    if (!path) path = "/usr/bin:/bin";
    char *copy = xstrdup(path);
    bool ok = false;
    char *save = NULL;
    for (char *tok = strtok_r(copy, ":", &save); tok; tok = strtok_r(NULL, ":", &save)) {
        char *p = join_path(*tok ? tok : ".", name);
        if (access(p, X_OK) == 0) ok = true;
        free(p);
        if (ok) break;
    }
    free(copy);
    return ok;
}
static char **split_words(const char *s, int *outn)
{
    *outn = 0;
    if (!s) return NULL;
    char **v = NULL; int cap = 0;
    const char *p = s;
    while (*p) {
        while (*p == ' ' || *p == '\t' || *p == '\n') p++;
        if (!*p) break;
        const char *start = p;
        while (*p && *p != ' ' && *p != '\t' && *p != '\n') p++;
        if (*outn == cap) { cap = cap ? cap * 2 : 8; v = xrealloc(v, (size_t)(cap + 1) * sizeof *v); }
        v[(*outn)++] = xstrndup(start, (size_t)(p - start));
    }
    if (v) v[*outn] = NULL;
    return v;
}

/* Run argv in the foreground with curses suspended.  pause_on_error
 * implements the "'Enter' to continue" pause; wait_always forces it. */
static int run_argv_fg(char *const argv[], bool wait_always, bool pause_on_error)
{
    if (!argv || !argv[0]) return 1;
    suspend_curses();
    pid_t pid = fork();
    if (pid == 0) {
        execvp(argv[0], argv);
        _exit(127);
    }
    int status = 0;
    if (pid > 0) while (waitpid(pid, &status, 0) < 0 && errno == EINTR) { }
    int rc = (pid > 0 && WIFEXITED(status)) ? WEXITSTATUS(status) : 1;
    if (wait_always || (pause_on_error && rc != 0)) wait_enter();
    resume_curses();
    return rc;
}
static int run_shell_fg(const char *cmd, bool wait_always, bool pause_on_error)
{
    const char *sh = G.shell ? G.shell : "/bin/sh";
    char *argv[4] = { (char*)sh, (char*)"-c", (char*)cmd, NULL };
    return run_argv_fg(argv, wait_always, pause_on_error);
}
/* Run a word-split command (EDITOR/PAGER/opener style) with an optional
 * trailing path argument. */
static int run_words_fg(const char *cmdline, const char *extra, bool wait_always)
{
    int n = 0; char **words = split_words(cmdline, &n);
    if (!n) { freev(words, n); return 1; }
    if (!find_in_path(words[0])) { freev(words, n); return 127; }
    char **argv = xmalloc((size_t)(n + 2) * sizeof *argv);
    for (int i = 0; i < n; i++) argv[i] = words[i];
    int m = n;
    if (extra) argv[m++] = (char*)extra;
    argv[m] = NULL;
    int rc = run_argv_fg(argv, wait_always, false);
    free(argv); freev(words, n);
    return rc;
}
static void run_detached_words(const char *cmdline, const char *extra)
{
    int n = 0; char **words = split_words(cmdline, &n);
    if (!n) { freev(words, n); return; }
    if (!find_in_path(words[0])) { freev(words, n); return; }
    pid_t pid = fork();
    if (pid == 0) {
        pid_t p2 = fork();
        if (p2 == 0) {
            setsid();
            int fd = open("/dev/null", O_RDWR);
            if (fd >= 0) { dup2(fd, 0); dup2(fd, 1); dup2(fd, 2); if (fd > 2) close(fd); }
            char **argv = xmalloc((size_t)(n + 2) * sizeof *argv);
            for (int i = 0; i < n; i++) argv[i] = words[i];
            int m = n; if (extra) argv[m++] = (char*)extra; argv[m] = NULL;
            execvp(argv[0], argv);
            _exit(127);
        }
        _exit(0);
    }
    if (pid > 0) { int st; waitpid(pid, &st, 0); }
    freev(words, n);
}

static const char *editor_cmd(bool internal)
{
    const char *vis = getenv("VISUAL");
    const char *ed = getenv("EDITOR");
    if (vis && !*vis) vis = NULL;
    if (ed && !*ed) ed = NULL;
    if (internal && gcfg.editor_internal) return ed ? ed : (vis ? vis : "vi");
    return vis ? vis : (ed ? ed : "vi");
}
static int edit_file(const char *path, bool internal)
{
    return run_words_fg(editor_cmd(internal), path, false);
}
static bool is_text_file(const char *path)
{
    if (!find_in_path("file")) return false;
    int pipefd[2];
    if (pipe(pipefd)) return false;
    pid_t pid = fork();
    if (pid == 0) {
        dup2(pipefd[1], 1);
        close(pipefd[0]); close(pipefd[1]);
        int fd = open("/dev/null", O_WRONLY); if (fd >= 0) dup2(fd, 2);
        execlp("file", "file", "-biL", path, (char*)NULL);
        _exit(127);
    }
    close(pipefd[1]);
    char buf[256]; ssize_t r = read(pipefd[0], buf, sizeof buf - 1);
    close(pipefd[0]);
    int st; waitpid(pid, &st, 0);
    if (r <= 0) return false;
    buf[r] = 0;
    return strncmp(buf, "text/", 5) == 0;
}

/* FIFO (preview) */
static int fifo_fd = -1;
static void fifo_notify(const char *path)
{
    if (!G.fifo_path || gcfg.fifo_mode == 1 || !path) return;
    if (fifo_fd < 0) {
        fifo_fd = open(G.fifo_path, O_WRONLY | O_NONBLOCK);
        if (fifo_fd < 0) return;
    }
    char *buf = NULL;
    if (asprintf(&buf, "%s\n", path) < 0) return;
    ssize_t w = write(fifo_fd, buf, strlen(buf));
    free(buf);
    if (w < 0 && errno != EAGAIN) { close(fifo_fd); fifo_fd = -1; }
}

/* Temp files /tmp/.nnnXXXXXX */
static char *make_tmpfile(void)
{
    const char *td = G.tmpdir ? G.tmpdir : "/tmp";
    char *tmpl = NULL;
    if (asprintf(&tmpl, "%s/.nnnXXXXXX", td) < 0) return NULL;
    int fd = mkstemp(tmpl);
    if (fd < 0) { free(tmpl); return NULL; }
    close(fd);
    return tmpl;
}
static void show_in_pager(const char *tmpfile)
{
    const char *pager = G.pager ? G.pager : "less";
    run_words_fg(pager, tmpfile, false);
}

/* ------------------------------------------------------------------ */
/* bookmarks (NNN_BMS) and plugins (NNN_PLUG)                           */

typedef struct { char key; char *value; } KeyVal;
static KeyVal *bms = NULL; static int nbms = 0;
static KeyVal *plugs = NULL; static int nplugs = 0;
static char *markdir = NULL;   /* directory marked with ',' (key ',') */

static bool parse_keyvals(const char *s, KeyVal **out, int *outn)
{
    *out = NULL; *outn = 0;
    if (!s || !*s) return true;
    char *copy = xstrdup(s);
    int cap = 0;
    char *save = NULL;
    /* strtok would collapse ";;" (which must be an error), so split
     * manually on ';'. */
    char *p = copy;
    bool ok = true;
    for (;;) {
        char *semi = strchr(p, ';');
        if (semi) *semi = 0;
        if (!*p) {
            if (semi) {
                if (semi[1] == 0 && *outn > 0) { /* trailing ';' is fine */ }
                else ok = false;
            }
        } else {
            if (strlen(p) < 3 || p[1] != ':') ok = false;
            else {
                if (*outn == cap) { cap = cap ? cap * 2 : 8; *out = xrealloc(*out, (size_t)cap * sizeof(KeyVal)); }
                (*out)[*outn].key = p[0];
                (*out)[*outn].value = xstrdup(p + 2);
                (*outn)++;
            }
        }
        if (!semi || !ok) break;
        p = semi + 1;
        if (!*p) break; /* trailing */
    }
    free(copy);
    if (!ok) {
        for (int i = 0; i < *outn; i++) free((*out)[i].value);
        free(*out); *out = NULL; *outn = 0;
    }
    return ok;
}
