/* Run xargs with the selection file on stdin. */
static int run_xargs(char *const xargv[], bool wait_always)
{
    suspend_curses();
    pid_t pid = fork();
    if (pid == 0) {
        if (G.selpath) {
            int fd = open(G.selpath, O_RDONLY);
            if (fd >= 0) { dup2(fd, 0); close(fd); }
        }
        execvp("xargs", xargv);
        _exit(127);
    }
    int status = 0;
    if (pid > 0) while (waitpid(pid, &status, 0) < 0 && errno == EINTR) { }
    int rc = (pid > 0 && WIFEXITED(status)) ? WEXITSTATUS(status) : 1;
    if (wait_always || rc != 0) wait_enter();
    resume_curses();
    return rc;
}
static int run_sel_sh(const char *inner)
{
