/* Delete or trash the hovered entry or the selection. */
static void op_delete(bool force_rm)
{
    Entry *e = cur_entry();
    if (!e) return;
    int src = choose_opsrc(true);
    if (src == OPSRC_NONE) return;
    bool trash = !force_rm && G.trash_set;
    if (src == OPSRC_CURRENT) {
        char *prompt = NULL;
        if (asprintf(&prompt, "%s '%s'?", trash ? "trash" : "rm -rf", e->name) < 0) return;
