            else if (t == '2') { char *a[] = {(char*)"gio", (char*)"trash", p, NULL}; run_argv_fg(a, false, true); }
        } else {
            char *a[] = {(char*)"rm", (char*)"-vrf", (char*)"--", p, NULL};
            run_argv_fg(a, false, true);
        }
        /* drop a now-deleted path from the in-memory selection */
        int si = sel_index(p);
        if (si >= 0) { sel_remove_at(si); sel_write_file(); }
        free(p);
    } else {
        int n = 0; bool borrowed = false;
        char **paths = effective_selection(&n, &borrowed);
        if (!borrowed) freev(paths, n);
