/* Make parents of a (possibly relative) destination path inside the
 * current directory; returns the absolute destination or NULL. */
static char *dest_abs_mkdir(const char *input, bool parent_only)
{
    char *dest = is_abs_path(input) ? xstrdup(input) : join_path(CTX()->path, input);
    char *parent = parent_only ? dir_name_dup(input) : NULL;
    char *par_abs;
    if (parent_only) {
        par_abs = is_abs_path(parent) ? parent : join_path(CTX()->path, parent);
        if (parent_only && par_abs != parent) { /* parent is leaked below */ }
    } else par_abs = dir_name_dup(dest);
    if (mkdir_p(par_abs) != 0) { free(dest); free(par_abs); if (parent && parent != par_abs) free(parent); return NULL; }
    if (parent && parent != par_abs) free(parent);
    free(par_abs);
    return dest;
}

/* Create a new file/dir/link ('n').  If prefill_name is non-NULL the
 * name prompt is shown directly with that name (used at start-up for
 * a non-existent PATH), creating a regular file. */
static void op_create(const char *prefill_name)
{
    int type = 'f';
    if (!prefill_name) {
        int k = read_choice("['f'ile]/'d'ir/'s'ym/'h'ard?");
        if (k == '\n' || k == '\r' || k == KEY_ENTER) type = 'f';
        else if (k == 'f' || k == 'd' || k == 's' || k == 'h') type = k;
        else return;
    }
    char *name = read_line("[path/]name: ", prefill_name ? prefill_name : "");
    if (!name) return;
    const char *bn = base_name(name);
    if (!*bn) { free(name); return; }
    char *dest = is_abs_path(name) ? xstrdup(name) : join_path(CTX()->path, name);
    char *hover_after = NULL;
    /* does the destination exist? (lstat, so a dangling link counts) */
    struct stat st;
    bool exists = lstat(dest, &st) == 0;
    if (exists && type == 'f' && S_ISREG(st.st_mode)) {
        if (!confirm_prompt("overwrite?")) { free(dest); free(name); return; }
        int fd = open(dest, O_WRONLY | O_TRUNC, 0600);
        if (fd >= 0) close(fd); else set_errmsg();
        hover_after = xstrdup(bn);
    } else if (exists) {
        set_msg("entry exists");
        free(dest); free(name);
        return;
    } else {
        char *par = dir_name_dup(dest);
        if (mkdir_p(par) != 0) { set_errmsg(); free(par); free(dest); free(name); return; }
        free(par);
        if (type == 'f') {
            int fd = open(dest, O_WRONLY | O_CREAT | O_EXCL, 0600);
            if (fd >= 0) close(fd); else { set_errmsg(); free(dest); free(name); return; }
        } else if (type == 'd') {
            if (mkdir_p(dest) != 0) { set_errmsg(); free(dest); free(name); return; }
        } else {
            Entry *e = cur_entry();
            if (!e) { free(dest); free(name); return; }
            char *src = entry_path(e);
            int rc = (type == 's') ? symlink(src, dest) : link(src, dest);
            if (rc) set_errmsg();
            free(src);
            /* cursor stays on the source entry for links */
            hover_after = xstrdup(e->name);
            free(dest); free(name);
            after_op_reload(hover_after);
            free(hover_after);
            return;
        }
        hover_after = xstrdup(bn);
    }
    /* Land on the topmost new component in the current directory. */
    if (strchr(name, '/')) {
        /* if the created path is inside a subdir, hover that subdir if
         * the file itself is not in the current listing */
        char *rel = name;
        if (is_abs_path(name)) {
            size_t pl = strlen(CTX()->path);
            rel = (!strncmp(name, CTX()->path, pl) && name[pl] == '/') ? name + pl + 1 : NULL;
        }
        if (rel) {
            char *slash = strchr(rel, '/');
            if (slash) { free(hover_after); hover_after = xstrndup(rel, (size_t)(slash - rel)); }
        } else {
            free(hover_after); hover_after = NULL;
        }
    }
    free(dest); free(name);
    after_op_reload(hover_after);
    free(hover_after);
}

/* Rename the hovered entry, or duplicate it when the name is left
 * unchanged at the first prompt. */
static void op_rename(void)
{
    Entry *e = cur_entry();
    if (!e) return;
    char *oldname = xstrdup(e->name);
    char *oldpath = entry_path(e);
    char *input = read_line("", oldname);
    if (!input) { free(oldname); free(oldpath); return; }
    bool duplicate = strcmp(input, oldname) == 0;
    char *newname = input;
    if (duplicate) {
        free(input);
        newname = read_line("copy [path/]name: ", oldname);
        if (!newname) { free(oldname); free(oldpath); return; }
        if (!strcmp(newname, oldname)) { free(newname); free(oldname); free(oldpath); return; }
    }
    if (!*newname || !*base_name(newname)) { free(newname); free(oldname); free(oldpath); return; }
    char *dest = is_abs_path(newname) ? xstrdup(newname) : join_path(CTX()->path, newname);
    struct stat st;
    if (lstat(dest, &st) == 0) {
        if (!confirm_prompt("overwrite?")) { free(dest); free(newname); free(oldname); free(oldpath); return; }
    }
    char *par = dir_name_dup(dest);
    if (mkdir_p(par) != 0) { set_errmsg(); free(par); free(dest); free(newname); free(oldname); free(oldpath); return; }
    free(par);
    char *hover = xstrdup(base_name(newname));
    if (duplicate) {
        char *a[] = {(char*)"cp", (char*)"-Rp", (char*)"--", oldpath, dest, NULL};
        /* nnn duplicates with an interactive cp; the observable result
         * (copy made, cursor on the copy) matches this invocation. */
        a[1] = (char*)"-iRp";
        run_argv_fg(a, false, true);
    } else {
        if (rename(oldpath, dest) != 0) {
            /* cross-device fall-back */
            char *a[] = {(char*)"mv", (char*)"-i", (char*)"--", oldpath, dest, NULL};
            run_argv_fg(a, false, true);
        }
        int si = sel_index(oldpath);
        if (si >= 0) { free(sel[si]); sel[si] = xstrdup(dest); sel_write_file(); }
    }
    free(dest); free(oldpath); free(oldname);
    /* If renamed out of this directory the name won't be found and the
     * cursor simply stays at its index. */
    char *rel_hover = NULL;
    if (!strchr(newname, '/')) rel_hover = hover;
    else {
        char *par2 = dir_name_dup(newname);
        if (!strcmp(par2, ".")) rel_hover = hover;
        free(par2);
    }
    after_op_reload(rel_hover);
    free(hover); free(newname);
}

/* cp/mv selection "as" ('w'): destination names are edited in the
 * editor as a file of "#<source>\n<name>" pairs. */
static void op_copy_move_as(void)
{
    int n = 0; bool borrowed = false;
    char **paths = effective_selection(&n, &borrowed);
    if (!n) { if (!borrowed) freev(paths, n); set_msg("0 selected"); return; }
    char **srcs = xmalloc((size_t)n * sizeof *srcs);
    for (int i = 0; i < n; i++) srcs[i] = xstrdup(paths[i]);
    if (!borrowed) freev(paths, n);
    int k = read_choice("'c'p/'m'v as?");
    if (k != 'c' && k != 'm') { freev(srcs, n); return; }
    bool move = (k == 'm');
    char *tmp = make_tmpfile();
    if (!tmp) { freev(srcs, n); return; }
    FILE *f = fopen(tmp, "wb");
    if (f) {
        for (int i = 0; i < n; i++) fprintf(f, "#%s\n%s\n", srcs[i], base_name(srcs[i]));
        fclose(f);
    }
    edit_file(tmp, true);
    /* Read back pairs. */
    char **dests = xmalloc((size_t)n * sizeof *dests);
    for (int i = 0; i < n; i++) dests[i] = NULL;
    f = fopen(tmp, "rb");
    if (f) {
        char *line = NULL; size_t lc = 0; ssize_t lr; int idx = -1;
        char *cursrc = NULL;
        while ((lr = getline(&line, &lc, f)) > 0) {
            while (lr > 0 && (line[lr-1] == '\n' || line[lr-1] == '\r')) line[--lr] = 0;
            if (line[0] == '#') {
                free(cursrc); cursrc = xstrdup(line + 1); idx++;
                if (idx < n) { free(srcs[idx]); srcs[idx] = cursrc; cursrc = NULL; }
            } else if (idx >= 0 && idx < n) {
                free(dests[idx]); dests[idx] = xstrdup(line);
            }
        }
        free(line); free(cursrc);
        fclose(f);
    }
    /* The reference binary leaves this editor buffer behind. */
    free(tmp);
    int rc_all = 0;
    char *lasthover = NULL;
    for (int i = 0; i < n; i++) {
        if (!dests[i] || !*dests[i]) continue;
        char *dest = is_abs_path(dests[i]) ? xstrdup(dests[i]) : join_path(CTX()->path, dests[i]);
        int rc;
        if (move) { char *a[] = {(char*)(gcfg.advcp ? "mvg" : "mv"), (char*)(gcfg.advcp ? "-gi" : "-i"), (char*)"--", srcs[i], dest, NULL}; rc = run_argv_fg(a, false, true); }
        else { char *a[] = {(char*)(gcfg.advcp ? "cpg" : "cp"), (char*)(gcfg.advcp ? "-giRp" : "-iRp"), (char*)"--", srcs[i], dest, NULL}; rc = run_argv_fg(a, false, true); }
        if (rc) rc_all = rc;
        free(lasthover); lasthover = xstrdup(base_name(dest));
        free(dest);
    }
    if (!rc_all) sel_clear(true);
    after_op_reload(lasthover);
    free(lasthover);
    freev(dests, n); freev(srcs, n);
}

/* Toggle executable bits (*). */
static void op_toggle_exe(void)
{
    Entry *e = cur_entry();
    if (!e) return;
    char *p = entry_path(e);
    struct stat st;
    if (stat(p, &st) == 0) {
        mode_t m = st.st_mode;
        if (m & (S_IXUSR | S_IXGRP | S_IXOTH)) m &= ~(mode_t)(S_IXUSR | S_IXGRP | S_IXOTH);
        else m |= (S_IXUSR | S_IXGRP | S_IXOTH);
        if (chmod(p, m) != 0) set_errmsg();
    }
    char *h = xstrdup(e->name);
    free(p);
    after_op_reload(h);
    free(h);
}
