    }
    int status = 0;
    if (pid > 0) while (waitpid(pid, &status, 0) < 0 && errno == EINTR) { }
    int rc = (pid > 0 && WIFEXITED(status)) ? WEXITSTATUS(status) : 1;
    if (wait_always || rc != 0) wait_enter();
    resume_curses();
