    bool use_bsdtar = gcfg.bsdtar || find_in_path("bsdtar");
    bool iszip = !use_bsdtar && has_suffix_ci(dest, ".zip") && strcmp(dest + strlen(dest) - 4, ".zip") == 0;
    const char *tool = use_bsdtar ? "bsdtar" : iszip ? "zip" : "tar";
    char *hover = xstrdup(base_name(dest));
    if (src == OPSRC_CURRENT) {
