/* Open an archive: list / open (opener) / extract / mount. */
static bool g_picker_pick_and_exit = false;
static bool g_quit_all = false;
static int g_exit_code = 0;
static bool op_open_entry(Entry *e, bool enter_key);
static void op_archive_open(Entry *e, const char *path)
{
    int k = read_choice("['l's]/'o'pen/e'x'tract/'m'nt?");
    bool use_bsdtar = gcfg.bsdtar || find_in_path("bsdtar");
    bool iszip = !use_bsdtar && has_suffix_ci(e->name, ".zip") && strcmp(e->name + strlen(e->name) - 4, ".zip") == 0;
    if (k == '\n' || k == '\r' || k == KEY_ENTER || k == 'l') {
        char *tmp = make_tmpfile();
        if (!tmp) return;
        /* capture listing into the tmp file, then page it */
        FILE *out = fopen(tmp, "wb");
        if (out) fclose(out);
        suspend_curses();
        pid_t pid = fork();
        if (pid == 0) {
            int fd = open(tmp, O_WRONLY | O_TRUNC);
            if (fd >= 0) { dup2(fd, 1); dup2(fd, 2); close(fd); }
            if (iszip) execlp("unzip", "unzip", "-v", path, (char*)NULL);
            else execlp(use_bsdtar ? "bsdtar" : "tar", use_bsdtar ? "bsdtar" : "tar", "-tvf", path, (char*)NULL);
            _exit(127);
        }
        int st; if (pid > 0) waitpid(pid, &st, 0);
        resume_curses();
        show_in_pager(tmp);
        unlink(tmp); free(tmp);
        return;
    }
    if (k == 'o') {
        /* open with the normal opener despite being an archive */
        extern void open_with_opener(const char *path);
        open_with_opener(path);
        return;
    }
    if (k == 'x') {
        char *input = read_line("[path/]name: ", e->name);
        if (!input || !*input) { free(input); return; }
        char *dest = is_abs_path(input) ? xstrdup(input) : join_path(CTX()->path, input);
        free(input);
        struct stat st;
        if (stat(dest, &st) == 0 && !S_ISDIR(st.st_mode)) {
            set_msg("Not a directory");
            free(dest); return;
        }
        if (mkdir_p(dest) != 0) { set_errmsg(); free(dest); return; }
        if (chdir(dest) != 0) { set_errmsg(); free(dest); return; }
        if (iszip) { char *a[] = {(char*)"unzip", (char*)"-", (char*)path, NULL}; run_argv_fg(a, false, false); }
        else { char *a[] = {(char*)(use_bsdtar ? "bsdtar" : "tar"), (char*)"-xvf", (char*)path, NULL}; run_argv_fg(a, false, false); }
        char *absd = abs_path(dest);
        free(dest);
        change_dir_abs(absd, NULL);
        return;
    }
    if (k == 'm') {
        if (!find_in_path("archivemount")) { set_msg("install utility (archivemount)"); return; }
        char *mntdir = NULL;
        if (asprintf(&mntdir, "%s/%s", G.mountsdir, e->name) < 0) return;
        mkdir_p(mntdir);
        char *a[] = {(char*)"archivemount", (char*)path, mntdir, NULL};
        run_argv_fg(a, false, true);
        char *absd = abs_path(mntdir);
        free(mntdir);
        change_dir_abs(absd, NULL);
        return;
    }
    if (k != ESC_KEY) set_msg("invalid key");
}

void open_with_opener(const char *path)
{
    if (gcfg.editor_text && !gcfg.cli_opener && is_text_file(path)) {
        edit_file(path, false);
        return;
    }
    const char *prog = G.opener;
    if (!prog) {
        if (!find_in_path("xdg-open")) return;
        prog = "xdg-open";
    }
    int n = 0; char **w = split_words(prog, &n);
    /* A custom opener is a single program (no arguments); the desktop
     * opener fallback is used when the value does not resolve. */
    bool custom_ok = n == 1 && find_in_path(w[0]);
    freev(w, n);
    if (G.opener && !custom_ok) return;
    if (gcfg.cli_opener) run_words_fg(prog, path, false);
    else run_detached_words(prog, path);
}

static bool g_autoadvance = false;
static bool op_open_entry(Entry *e, bool enter_key)
{
    if (!e) return false;
    char *path = entry_path(e);
    if (e->is_dir) {
        char *absd = abs_path(path);
        free(path);
        return change_dir_abs(absd, NULL);
    }
    if (gcfg.picker_file) {
        if (sel_index(path) < 0) { sel_add(path); sel_write_file(); }
        g_picker_pick_and_exit = true;
        free(path);
        return true;
    }
    if (S_ISREG(e->mode) && e->size == 0) {
        set_msg("empty! edit/open with");
        free(path);
        return false;
    }
    if (gcfg.open_enter_only && !enter_key) { free(path); return false; }
    if (!e->is_dir && is_archive_name(e->name)) {
        op_archive_open(e, path);
        free(path);
        return true;
    }
    open_with_opener(path);
    free(path);
    return true;
}

/* Open with a user typed program ('o'). */
static char *read_line_native(const char *prompt);
static void op_open_with(void)
{
    Entry *e = cur_entry();
    if (!e) return;
    char *prog;
    if (gcfg.native_prompt) prog = read_line("open with: ", "");
    else prog = read_line_native("open with: ");
    if (!prog || !*prog) { free(prog); return; }
    int k = read_choice("['g'ui]/'c'li?");
    if (k != 'g' && k != 'c' && k != '\n' && k != '\r' && k != KEY_ENTER) { free(prog); return; }
    char *path = entry_path(e);
    if (k == 'c') run_words_fg(prog, path, false);
    else run_detached_words(prog, path);
    free(path); free(prog);
    if (g_autoadvance && CTX()->cur + 1 < nview) CTX()->cur++;
}

/* File statistics popup ('f'). */
static char *capture_cmd(char *const argv[])
{
    int pipefd[2];
    if (pipe(pipefd)) return xstrdup("");
    pid_t pid = fork();
    if (pid == 0) {
        dup2(pipefd[1], 1); dup2(pipefd[1], 2);
        close(pipefd[0]); close(pipefd[1]);
        execvp(argv[0], argv);
        _exit(127);
    }
    close(pipefd[1]);
    size_t cap = 8192, len = 0;
    char *buf = xmalloc(cap);
    for (;;) {
        if (len + 4096 >= cap) { cap *= 2; buf = xrealloc(buf, cap); }
        ssize_t r = read(pipefd[0], buf + len, cap - len - 1);
        if (r <= 0) break;
        len += (size_t)r;
    }
    close(pipefd[0]);
    int st; if (pid > 0) waitpid(pid, &st, 0);
    buf[len] = 0;
    return buf;
}
static void op_file_stats(void)
{
    if (!nview) return;
    int idx = CTX()->cur;
    int xoff = 0, yoff = 0;
    for (;;) {
        Entry *e = view[idx];
        char *path = entry_path(e);
        /* build content */
        char *parts[3]; int np = 0;
        if (find_in_path("stat")) { char *a[] = {(char*)"stat", path, NULL}; parts[np++] = capture_cmd(a); }
        if (find_in_path("file")) {
            char *a[] = {(char*)"file", (char*)"-b", path, NULL}; parts[np++] = capture_cmd(a);
            char *b[] = {(char*)"file", (char*)"-biL", path, NULL}; parts[np++] = capture_cmd(b);
        }
        size_t tot = 1; for (int i = 0; i < np; i++) tot += strlen(parts[i]) + 1;
        char *text = xmalloc(tot); text[0] = 0;
        for (int i = 0; i < np; i++) { strcat(text, parts[i]); free(parts[i]); }
        /* split lines */
        char **lines = NULL; int nl = 0, cl = 0;
        char *save = NULL;
        for (char *tok = strtok_r(text, "\n", &save); tok; tok = strtok_r(NULL, "\n", &save)) {
            if (nl == cl) { cl = cl ? cl * 2 : 16; lines = xrealloc(lines, (size_t)cl * sizeof *lines); }
            lines[nl++] = tok;
        }
        int action = 0; /* 0 close, 1 next, -1 prev */
        for (;;) {
            draw();
            int h = LINES - 4; if (h > 20) h = 20; if (h < 4) h = LINES > 4 ? LINES : 4;
            int w = COLS * 3 / 4; if (w < 20) w = COLS; if (w > COLS) w = COLS;
            int y = (LINES - h) / 2; if (y < 0) y = 0;
            int x = (COLS - w) / 2; if (x < 0) x = 0;
            WINDOW *win = newwin(h, w, y, x);
            box(win, 0, 0);
            char title[128];
            snprintf(title, sizeof title, " %d/%d ", idx + 1, nview);
            wmove(win, 0, 2); waddstr(win, title);
            wattron(win, A_BOLD); waddstr(win, e->name); wattroff(win, A_BOLD);
            waddch(win, ' ');
            wmove(win, h - 1, 1);
            waddstr(win, "q/ESC:close  arrows:scroll  n/j:next  p/k:prev");
            int maxlen = 0;
            for (int i = 0; i < nl; i++) { int L = (int)strlen(lines[i]); if (L > maxlen) maxlen = L; }
            int textrows = h - 4;
            if (yoff > nl - 1) yoff = nl ? nl - 1 : 0;
            if (yoff < 0) yoff = 0;
            for (int i = 0; i < textrows && yoff + i < nl; i++) {
                wmove(win, 2 + i, 1);
                const char *ln = lines[yoff + i];
                if ((int)strlen(ln) > xoff) waddstr(win, ln + xoff);
            }
            if (maxlen - xoff > w - 2) mvwaddch(win, h - 2, w - 2, '>');
            if (xoff > 0) mvwaddch(win, h - 2, 1, '<');
            wrefresh(win);
            int k = get_key(NULL);
            delwin(win);
            touchwin(stdscr);
            if (k == 'q' || k == ESC_KEY) { action = 0; break; }
            if (k == 'n' || k == 'j') { if (idx + 1 < nview) { action = 1; } else { action = 0; } if (action) break; else continue; }
            if (k == 'p' || k == 'k') { if (idx > 0) { action = -1; break; } else continue; }
            if (k == KEY_DOWN) { if (yoff + textrows < nl) yoff++; continue; }
            if (k == KEY_UP) { if (yoff > 0) yoff--; continue; }
            if (k == KEY_RIGHT) { xoff++; continue; }
            if (k == KEY_LEFT) { if (xoff > 0) xoff--; continue; }
            if (k == KEY_NPAGE) { yoff += textrows; if (yoff > nl - 1) yoff = nl ? nl - 1 : 0; continue; }
            if (k == KEY_PPAGE) { yoff -= textrows; if (yoff < 0) yoff = 0; continue; }
        }
        free(lines); free(text); free(path);
        if (action == 1) { idx++; xoff = yoff = 0; continue; }
        if (action == -1) { idx--; xoff = yoff = 0; continue; }
        break;
    }
}

