        char *path = entry_path(e);
        /* build content */
        char *parts[3]; int np = 0;
        if (find_in_path("stat")) { char *a[] = {(char*)"stat", path, NULL}; parts[np++] = capture_cmd(a); }
        if (find_in_path("file")) {
            char *a[] = {(char*)"file", (char*)"-b", path, NULL}; parts[np++] = capture_cmd(a);
            char *b[] = {(char*)"file", (char*)"-biL", path, NULL}; parts[np++] = capture_cmd(b);
        }
        size_t tot = 1; for (int i = 0; i < np; i++) tot += strlen(parts[i]) + 1;
        char *text = xmalloc(tot); text[0] = 0;
        for (int i = 0; i < np; i++) { strcat(text, parts[i]); free(parts[i]); }
        /* split lines */
        char **lines = NULL; int nl = 0, cl = 0;
        char *save = NULL;
        for (char *tok = strtok_r(text, "\n", &save); tok; tok = strtok_r(NULL, "\n", &save)) {
            if (nl == cl) { cl = cl ? cl * 2 : 16; lines = xrealloc(lines, (size_t)cl * sizeof *lines); }
            lines[nl++] = tok;
        }
        int action = 0; /* 0 close, 1 next, -1 prev */
        for (;;) {
            draw();
            int h = LINES - 4; if (h > 20) h = 20; if (h < 4) h = LINES > 4 ? LINES : 4;
            int w = COLS * 3 / 4; if (w < 20) w = COLS; if (w > COLS) w = COLS;
            int y = (LINES - h) / 2; if (y < 0) y = 0;
            int x = (COLS - w) / 2; if (x < 0) x = 0;
            WINDOW *win = newwin(h, w, y, x);
            box(win, 0, 0);
            char title[128];
            snprintf(title, sizeof title, " %d/%d ", idx + 1, nview);
            wmove(win, 0, 2); waddstr(win, title);
            wattron(win, A_BOLD); waddstr(win, e->name); wattroff(win, A_BOLD);
            waddch(win, ' ');
            wmove(win, h - 1, 1);
            waddstr(win, "q/ESC:close  arrows:scroll  n/j:next  p/k:prev");
            int maxlen = 0;
            for (int i = 0; i < nl; i++) { int L = (int)strlen(lines[i]); if (L > maxlen) maxlen = L; }
            int textrows = h - 4;
            if (yoff > nl - 1) yoff = nl ? nl - 1 : 0;
            if (yoff < 0) yoff = 0;
            for (int i = 0; i < textrows && yoff + i < nl; i++) {
                wmove(win, 2 + i, 1);
                const char *ln = lines[yoff + i];
                if ((int)strlen(ln) > xoff) waddstr(win, ln + xoff);
            }
            if (maxlen - xoff > w - 2) mvwaddch(win, h - 2, w - 2, '>');
            if (xoff > 0) mvwaddch(win, h - 2, 1, '<');
            wrefresh(win);
            int k = get_key(NULL);
            delwin(win);
            touchwin(stdscr);
