            if (xoff > 0) mvwaddch(win, h - 2, 1, '<');
            wrefresh(win);
            int k = get_key(NULL);
            delwin(win);
            touchwin(stdscr);
            if (k == 'q' || k == ESC_KEY) { action = 0; break; }
            if (k == 'n' || k == 'j') { if (idx + 1 < nview) { action = 1; } else { action = 0; } if (action) break; else continue; }
            if (k == 'p' || k == 'k') { if (idx > 0) { action = -1; break; } else continue; }
            if (k == KEY_DOWN) { if (yoff + textrows < nl) yoff++; continue; }
            if (k == KEY_UP) { if (yoff > 0) yoff--; continue; }
            if (k == KEY_RIGHT) { xoff++; continue; }
            if (k == KEY_LEFT) { if (xoff > 0) xoff--; continue; }
            if (k == KEY_NPAGE) { yoff += textrows; if (yoff > nl - 1) yoff = nl ? nl - 1 : 0; continue; }
            if (k == KEY_PPAGE) { yoff -= textrows; if (yoff < 0) yoff = 0; continue; }
        }
        free(lines); free(text); free(path);
        if (action == 1) { idx++; xoff = yoff = 0; continue; }
        if (action == -1) { idx--; xoff = yoff = 0; continue; }
        break;
    }
}

