/* Batch rename ('r'). */
static void op_batch_rename(void)
{
    int src = choose_opsrc(true);
    if (src == OPSRC_NONE) return;
    char **oldnames = NULL, **oldpaths = NULL;
    int n = 0;
    if (src == OPSRC_CURRENT) {
        n = nview;
        oldnames = xmalloc((size_t)(n ? n : 1) * sizeof *oldnames);
        oldpaths = xmalloc((size_t)(n ? n : 1) * sizeof *oldpaths);
        for (int i = 0; i < n; i++) {
            oldnames[i] = xstrdup(view[i]->name);
            oldpaths[i] = entry_path(view[i]);
        }
    } else {
        bool borrowed = false;
        char **paths = effective_selection(&n, &borrowed);
        oldnames = xmalloc((size_t)(n ? n : 1) * sizeof *oldnames);
        oldpaths = xmalloc((size_t)(n ? n : 1) * sizeof *oldpaths);
        for (int i = 0; i < n; i++) {
            oldpaths[i] = paths[i];
            oldnames[i] = xstrdup(paths[i]); /* editor shows absolute paths */
        }
        if (borrowed) {
            /* effective_selection borrowed the internal array; copy it */
            for (int i = 0; i < n; i++) oldpaths[i] = xstrdup(paths[i]);
        }
    }
    if (!n) { free(oldnames); free(oldpaths); return; }
    char *tmp = make_tmpfile();
    if (!tmp) { freev(oldnames, n); freev(oldpaths, n); return; }
    FILE *f = fopen(tmp, "wb");
    if (f) { for (int i = 0; i < n; i++) fprintf(f, "%s\n", oldnames[i]); fclose(f); }
    /* Environment the reference binary exposes to the editor here. */
    char *oldhidden = getenv("NNN_INCLUDE_HIDDEN") ? xstrdup(getenv("NNN_INCLUDE_HIDDEN")) : NULL;
    char *oldpref = getenv("NNN_PREFER_SELECTION") ? xstrdup(getenv("NNN_PREFER_SELECTION")) : NULL;
    char *oldlist = getenv("NNN_LIST") ? xstrdup(getenv("NNN_LIST")) : NULL;
    setenv("NNN_INCLUDE_HIDDEN", CTX()->hidden ? "1" : "0", 1);
    setenv("NNN_PREFER_SELECTION", gcfg.use_selection ? "1" : "0", 1);
