    edit_file(tmp, true);
    if (oldhidden) setenv("NNN_INCLUDE_HIDDEN", oldhidden, 1); else unsetenv("NNN_INCLUDE_HIDDEN");
    if (oldpref) setenv("NNN_PREFER_SELECTION", oldpref, 1); else unsetenv("NNN_PREFER_SELECTION");
    if (oldlist) setenv("NNN_LIST", oldlist, 1); else unsetenv("NNN_LIST");
    free(oldhidden); free(oldpref); free(oldlist);
    /* entries may have been reloaded by the directory watcher while the
     * editor ran; old paths/names are self-contained copies. */
    f = fopen(tmp, "rb");
    char **newnames = xmalloc((size_t)n * sizeof *newnames);
    for (int i = 0; i < n; i++) newnames[i] = NULL;
    if (f) {
        char *line = NULL; size_t lc = 0; int i = 0;
        while (i < n && getline(&line, &lc, f) > 0) {
            size_t L = strlen(line);
            while (L && (line[L-1] == '\n' || line[L-1] == '\r')) line[--L] = 0;
            newnames[i++] = xstrdup(line);
        }
        free(line); fclose(f);
    }
    unlink(tmp); free(tmp);
    char *hovername = cur_entry() ? xstrdup(cur_entry()->name) : NULL;
    for (int i = 0; i < n; i++) {
        if (!newnames[i] || !*newnames[i]) continue;
        if (!strcmp(newnames[i], oldnames[i])) continue;
