        if (src == OPSRC_SEL && is_abs_path(newnames[i])) dest = xstrdup(newnames[i]);
        else if (src == OPSRC_SEL) {
            char *par = dir_name_dup(oldpaths[i]);
            dest = join_path(par, newnames[i]); free(par);
        } else dest = is_abs_path(newnames[i]) ? xstrdup(newnames[i]) : join_path(CTX()->path, newnames[i]);
        if (strcmp(dest, oldpaths[i])) {
            char *a[] = {(char*)"mv", (char*)"-i", (char*)"--", oldnames[i], newnames[i], NULL};
