/* Edit the selection list ('E'). */
static void op_edit_selection(void)
{
    if (!nsel) return;
    char *tmp = make_tmpfile();
    if (!tmp) return;
    FILE *f = fopen(tmp, "wb");
    if (f) { for (int i = 0; i < nsel; i++) fprintf(f, "%s\n", sel[i]); fclose(f); }
    edit_file(tmp, true);
    sel_clear(false);
    f = fopen(tmp, "rb");
    if (f) {
        char *line = NULL; size_t lc = 0;
        while (getline(&line, &lc, f) > 0) {
            size_t L = strlen(line);
            while (L && (line[L-1] == '\n' || line[L-1] == '\r')) line[--L] = 0;
            if (*line) sel_add(line);
        }
        free(line); fclose(f);
    }
    unlink(tmp); free(tmp);
    sel_write_file();
    sel_sync_flags();
    if (nview) CTX()->cur = 0;
}

/* Export the current listing ('>'): write names to a tmp file, open it
