/* Total size of the selected files visible in the current listing ('S'). */
static unsigned long long dir_size_count = 0;
static int ftw_count(const char *fpath, const struct stat *sb, int type, struct FTW *ftw)
{
    (void)fpath; (void)type; (void)ftw;
    if (sb) dir_size_count += (unsigned long long)sb->st_size;
    return 0;
}
static void op_listed_sel_size(void)
{
    unsigned long long total = 0;
    for (int i = 0; i < nview; i++) {
        if (!view[i]->selected) continue;
        if (view[i]->is_dir && !view[i]->is_lnk) {
            char *p = entry_path(view[i]);
            dir_size_count = 0;
            nftw(p, ftw_count, 10, FTW_PHYS);
            total += dir_size_count;
            free(p);
        } else total += (unsigned long long)view[i]->size;
    }
    char sz[32]; human_size(total, sz, sizeof sz);
    set_msg(sz);
}

/* --- native (cooked terminal) prompts --- */
static char *read_line_native(const char *prompt)
{
    suspend_curses();
    fputs(prompt, stdout); fflush(stdout);
    char *line = NULL; size_t cap = 0;
    ssize_t r = getline(&line, &cap, stdin);
    resume_curses();
    if (r < 0) { free(line); return NULL; }
    while (r > 0 && (line[r-1] == '\n' || line[r-1] == '\r')) line[--r] = 0;
    return line;
}

static void add_history(const char *line)
{
    if (!gcfg.history || !G.historypath || !*line) return;
    FILE *f = fopen(G.historypath, "ab");
    if (f) { fputs(line, f); fputc('\n', f); fclose(f); }
}

/* Command prompt (']'). */
static void op_cmd_prompt(void)
{
    if (gcfg.native_prompt) {
        for (;;) {
            char *cmd = read_line(">>> ", "");
            if (!cmd || !*cmd) { free(cmd); break; }
            add_history(cmd);
            run_shell_fg(cmd, true, false);
            free(cmd);
        }
        return;
    }
    suspend_curses();
    putchar('\n');
    for (;;) {
        fputs(">>> ", stdout); fflush(stdout);
        char *line = NULL; size_t cap = 0;
        ssize_t r = getline(&line, &cap, stdin);
        if (r < 0) { free(line); break; }
        while (r > 0 && (line[r-1] == '\n' || line[r-1] == '\r')) line[--r] = 0;
        if (!*line) { free(line); break; }
        add_history(line);
        fflush(stdout);
        const char *sh = G.shell ? G.shell : "/bin/sh";
        pid_t pid = fork();
        if (pid == 0) {
            signal(SIGINT, SIG_DFL); signal(SIGQUIT, SIG_DFL);
            execl(sh, sh, "-c", line, (char*)NULL);
            _exit(127);
        }
        int st; if (pid > 0) waitpid(pid, &st, 0);
        free(line);
        wait_enter();
        putchar('\n');
    }
    resume_curses();
}

/* Spawn a shell ('!'). */
static void prepare_shell_env(void);
static void restore_shell_env(void);
static char *saved_env[32];
static char *saved_env_names[32];
static int nsaved_env = 0;
static void save_and_set(const char *name, const char *val)
{
    if (nsaved_env < 32) {
        saved_env_names[nsaved_env] = xstrdup(name);
        const char *old = getenv(name);
        saved_env[nsaved_env] = old ? xstrdup(old) : NULL;
        nsaved_env++;
    }
    setenv(name, val, 1);
}
static void prepare_shell_env(void)
{
    nsaved_env = 0;
    Entry *e = cur_entry();
    save_and_set("nnn", e ? e->name : "");
    char lvl[32]; snprintf(lvl, sizeof lvl, "%ld", G.nnnlvl + 1);
    save_and_set("NNNLVL", lvl);
    save_and_set("NNN_INCLUDE_HIDDEN", CTX()->hidden ? "1" : "0");
    save_and_set("NNN_PREFER_SELECTION", gcfg.use_selection ? "1" : "0");
    for (int i = 0; i < MAX_CTX; i++) {
        if (!ctxs[i].active) continue;
        char dn[8], fn[8];
        snprintf(dn, sizeof dn, "d%d", i + 1);
        snprintf(fn, sizeof fn, "f%d", i + 1);
        save_and_set(dn, ctxs[i].path);
        char *hp;
        if (i == curctx) hp = e ? entry_path(e) : xstrdup(ctxs[i].path);
        else if (ctxs[i].hover) hp = join_path(ctxs[i].path, ctxs[i].hover);
        else hp = xstrdup(ctxs[i].path);
        save_and_set(fn, hp); free(hp);
    }
}
static void restore_shell_env(void)
{
    for (int i = 0; i < nsaved_env; i++) {
        if (saved_env[i]) setenv(saved_env_names[i], saved_env[i], 1);
        else unsetenv(saved_env_names[i]);
        free(saved_env_names[i]); free(saved_env[i]);
    }
    nsaved_env = 0;
}
static void op_shell(void)
{
    const char *sh = G.shell ? G.shell : "/bin/sh";
    prepare_shell_env();
    suspend_curses();
    pid_t pid = fork();
    if (pid == 0) {
        signal(SIGINT, SIG_DFL); signal(SIGQUIT, SIG_DFL); signal(SIGTSTP, SIG_DFL);
        execl(sh, sh, (char*)NULL);
        _exit(127);
    }
    int st; if (pid > 0) waitpid(pid, &st, 0);
    resume_curses();
    restore_shell_env();
    after_op_reload(NULL);
}

/* Launch an application ('='). */
static void op_launch_app(void)
{
    char *prog = read_line("app: ", "");
    if (!prog || !*prog) { free(prog); return; }
    run_detached_words(prog, NULL);
    free(prog);
}

/* Lock the terminal ('0'). */
static void op_lock(void)
{
    if (!find_in_path("vlock")) return;
    char *a[] = {(char*)"vlock", NULL};
    run_argv_fg(a, false, false);
}

/* Remote mounts ('c' / 'u'). */
static void op_connect_remote(void)
{
    const char *sshfs_cmd = getenv("NNN_SSHFS");
    const char *rclone_cmd = getenv("NNN_RCLONE");
    char sshfs_first[128] = "sshfs", rclone_first[128] = "rclone";
    if (sshfs_cmd) sscanf(sshfs_cmd, "%127s", sshfs_first);
    if (rclone_cmd) sscanf(rclone_cmd, "%127s", rclone_first);
    bool have_sshfs = find_in_path(sshfs_first), have_rclone = find_in_path(rclone_first);
    if (!have_sshfs && !have_rclone) { set_msg("install sshfs/rclone"); return; }
    bool use_rclone = false;
    if (have_sshfs && have_rclone) {
        int k = read_choice("'s'shfs/'r'clone?");
        if (k == 's') use_rclone = false;
        else if (k == 'r') use_rclone = true;
        else return;
    } else use_rclone = have_rclone;
    char *host = read_line("host[:dir] > ", "");
    if (!host || !*host) { free(host); return; }
    char *colon = strchr(host, ':');
    char *name = colon ? xstrndup(host, (size_t)(colon - host)) : xstrdup(host);
    char *mountdir = join_path(G.mountsdir, name);
    free(name);
    mkdir_p(mountdir);
    if (use_rclone) {
        const char *prefix = rclone_cmd ? rclone_cmd : "rclone mount";
        int n = 0; char **w = split_words(prefix, &n);
        char **argv = xmalloc((size_t)(n + 3) * sizeof *argv);
        for (int i = 0; i < n; i++) argv[i] = w[i];
        argv[n] = host; argv[n+1] = mountdir; argv[n+2] = NULL;
        /* run in background */
        pid_t pid = fork();
        if (pid == 0) {
            pid_t p2 = fork();
            if (p2 == 0) { setsid(); execvp(argv[0], argv); _exit(127); }
            _exit(0);
        }
        if (pid > 0) { int st; waitpid(pid, &st, 0); }
        free(argv); freev(w, n);
        set_msg("refresh if slow");
        draw();
        sleep(1);
    } else {
        const char *prefix = sshfs_cmd ? sshfs_cmd : "sshfs";
        int n = 0; char **w = split_words(prefix, &n);
        char **argv = xmalloc((size_t)(n + 3) * sizeof *argv);
        for (int i = 0; i < n; i++) argv[i] = w[i];
        argv[n] = host; argv[n+1] = mountdir; argv[n+2] = NULL;
        run_argv_fg(argv, false, false);
        free(argv); freev(w, n);
    }
    free(host);
    char *absd = abs_path(mountdir);
    free(mountdir);
    change_dir_abs(absd, NULL);
}
static void op_unmount(void)
{
    char *input = read_line("remote name (- for hovered): ", "");
    if (!input || !*input) { free(input); return; }
    const char *name = input;
    char *hovername = NULL;
    if (!strcmp(input, "-")) {
        Entry *e = cur_entry();
        hovername = e ? xstrdup(e->name) : xstrdup("");
        name = hovername;
    }
    char *mountdir = join_path(G.mountsdir, name);
    struct stat st;
    if (lstat(mountdir, &st) != 0) {
        set_msg(strerror(ENOENT));
        free(mountdir); free(hovername); free(input);
        return;
    }
    if (find_in_path("fusermount")) {
        char *a[] = {(char*)"fusermount", (char*)"-qu", mountdir, NULL};
        run_argv_fg(a, false, false);
    } else if (find_in_path("umount")) {
        char *a[] = {(char*)"umount", mountdir, NULL};
        run_argv_fg(a, false, false);
    }
    rmdir(mountdir);
    free(mountdir); free(hovername); free(input);
    after_op_reload(NULL);
}
