    char *line = NULL; size_t cap = 0;
    ssize_t r = getline(&line, &cap, stdin);
    resume_curses();
    if (r < 0) { free(line); return NULL; }
    while (r > 0 && (line[r-1] == '\n' || line[r-1] == '\r')) line[--r] = 0;
