    if (!val) { set_msg("invalid key"); return; }
    Entry *e = cur_entry();
    run_plugin_by_value(val, e ? e->name : "", CTX()->path, e ? e->name : "");
    after_op_reload(NULL);
}
static void op_plugin_prompt(void)
{
    char prompt[256];
    strcpy(prompt, "keys:");
    for (int i = 0; i < nplugs; i++) {
        char tmp[4] = { ' ', plugs[i].key, 0, 0 };
        strcat(prompt, tmp);
    }
