/* List directories for stdin / plugin 'l' data. */
static bool make_list_dir(char **paths, int n, char **outdir, char **outhover)
{
    char **abs = xmalloc((size_t)(n ? n : 1) * sizeof *abs);
    int m = 0;
    for (int i = 0; i < n; i++) {
        if (!paths[i] || !*paths[i]) continue;
        abs[m++] = abs_path(paths[i]);
    }
    if (!m) {
        /* an empty list still enters an (empty) list directory */
    }
    /* longest common directory prefix */
    char *common = NULL;
    if (m) {
        common = dir_name_dup(abs[0]);
        for (int i = 1; i < m; i++) {
            char *par = dir_name_dup(abs[i]);
            size_t j = 0;
            while (common[j] && par[j] && common[j] == par[j]) j++;
            while (j > 0 && common[j] != '/') j--;
            common[j ? j : 1] = 0;
            free(par);
            if (!strcmp(common, "/")) break;
        }
    }
    const char *td = G.tmpdir ? G.tmpdir : "/tmp";
    char *tmpl = NULL;
    if (asprintf(&tmpl, "%s/nnnXXXXXX", td) < 0) { freev(abs, m); free(common); return false; }
    if (!mkdtemp(tmpl)) { free(tmpl); freev(abs, m); free(common); return false; }
    chmod(tmpl, 0700);
    size_t cl = common ? strlen(common) : 0;
    for (int i = 0; i < m; i++) {
        const char *rel = abs[i] + cl;
        if (*rel == '/') rel++;
        if (!*rel) rel = base_name(abs[i]);
        char *target_link = join_path(tmpl, rel);
        char *par = dir_name_dup(target_link);
        mkdir_p(par); free(par);
        if (symlink(abs[i], target_link) != 0) { /* may be a duplicate */ }
        free(target_link);
    }
    *outdir = xstrdup(tmpl);
    *outhover = NULL;
    free(tmpl);
    freev(abs, m);
    free(common);
    return true;
}
static void remove_list_dir(const char *dir)
{
    if (!dir) return;
    char *a[] = {(char*)"rm", (char*)"-rf", (char*)"--", (char*)dir, NULL};
    pid_t pid = fork();
    if (pid == 0) { execvp("rm", a); _exit(127); }
    if (pid > 0) { int st; waitpid(pid, &st, 0); }
}

static int ctx_for_pipe(char spec);
static void process_pipe_data(char *data, size_t len)
{
    (void)len;
    if (len < 2) return;
    char spec = data[0];
    char cmd = data[1];
    int target = ctx_for_pipe(spec);
    if (target < 0 && cmd != 'p') return;
    if (cmd == 'p') { g_quit_all = true; return; }
    if (cmd == 'c') {
        char *path = xstrndup(data + 2, len - 2);
        /* path is the rest of the payload */
        curctx = target;
        char *absd = abs_path(path);
        free(path);
        struct stat st;
        if (stat(absd, &st) == 0 && S_ISDIR(st.st_mode)) {
            if (!ctxs[target].active) {
                /* activate below in change */
            }
            if (!ctxs[target].path) { ctxs[target].path = absd; ctxs[target].active = true; load_dir(NULL); }
            else change_dir_abs(absd, NULL);
        } else {
            goto_path(absd);
            free(absd);
        }
        return;
    }
    if (cmd == 'l') {
        /* NUL separated paths */
        char **paths = NULL; int n = 0, capn = 0;
        size_t start = 2;
        for (size_t i = 2; i <= len; i++) {
            if (i == len || data[i] == '\0') {
                if (i > start) {
                    if (n == capn) { capn = capn ? capn * 2 : 8; paths = xrealloc(paths, (size_t)capn * sizeof *paths); }
                    paths[n++] = xstrndup(data + start, i - start);
                }
                start = i + 1;
            }
        }
        curctx = target;
        char *ldir = NULL, *hov = NULL;
        if (make_list_dir(paths, n, &ldir, &hov)) {
            if (ctxs[target].listdir) remove_list_dir(ctxs[target].listdir);
            free(ctxs[target].listdir);
            ctxs[target].listdir = ldir;
            if (!ctxs[target].path) { ctxs[target].path = xstrdup(ldir); ctxs[target].active = true; load_dir(hov); }
            else change_dir_abs(xstrdup(ldir), hov);
        }
        free(hov);
        freev(paths, n);
        return;
    }
}
