/* Resolve a bookmark/start-up style path and go there. */
static bool goto_path(const char *path)
{
    if (!path || !*path) return false;
    char *absd = abs_path(path);
    struct stat st;
    if (stat(absd, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return change_dir_abs(absd, NULL);
        char *par = dir_name_dup(absd);
        char *hov = xstrdup(base_name(absd));
        free(absd);
        bool ok = true;
        if (strcmp(par, CTX()->path)) ok = change_dir_abs(par, hov);
        else {
            free(par);
            int idx = find_in_view(hov);
            if (idx >= 0) CTX()->cur = idx;
        }
        free(hov);
        return ok;
    }
    char *par = dir_name_dup(absd);
    free(absd);
    return change_dir_abs(par, NULL);
}

