/* Run a plugin script / shell command and process anything it writes
 * to $NNN_PIPE. */
static void run_plugin_cmd(const char *script, bool is_shell,
                           const char *arg_name, const char *arg_dir,
                           const char *nnnval)
{
    char *pipepath = NULL;
    if (asprintf(&pipepath, "%s/nnn-pipe.%ld", G.tmpdir ? G.tmpdir : "/tmp", (long)getpid()) < 0) return;
    unlink(pipepath);
    if (mkfifo(pipepath, 0600) != 0) { free(pipepath); return; }
    int rfd = open(pipepath, O_RDONLY | O_NONBLOCK);
    plugin_child_env(pipepath, nnnval);
    suspend_curses();
    pid_t pid = fork();
    if (pid == 0) {
        signal(SIGINT, SIG_DFL); signal(SIGQUIT, SIG_DFL);
        if (rfd >= 0) close(rfd);
        if (is_shell) {
            const char *sh = G.shell ? G.shell : "/bin/sh";
            execl(sh, sh, "-c", script, (char*)NULL);
        } else {
            execl(script, script, arg_name, arg_dir, (char*)NULL);
        }
        _exit(127);
    }
    /* collect pipe data while the plugin runs */
    char *data = NULL; size_t dlen = 0, dcap = 0;
    int status = 0;
    for (;;) {
        if (rfd >= 0) {
            char chunk[8192];
            ssize_t r;
            while ((r = read(rfd, chunk, sizeof chunk)) > 0) {
                if (dlen + (size_t)r + 1 > dcap) { dcap = (dlen + (size_t)r) * 2 + 128; data = xrealloc(data, dcap); }
                memcpy(data + dlen, chunk, (size_t)r); dlen += (size_t)r;
            }
        }
        pid_t w = waitpid(pid, &status, WNOHANG);
        if (w == pid) break;
        if (w < 0 && errno != EINTR) break;
        usleep(10000);
    }
    if (is_shell) wait_enter();
    if (rfd >= 0) {
        char chunk[8192]; ssize_t r;
        while ((r = read(rfd, chunk, sizeof chunk)) > 0) {
            if (dlen + (size_t)r + 1 > dcap) { dcap = (dlen + (size_t)r) * 2 + 128; data = xrealloc(data, dcap); }
            memcpy(data + dlen, chunk, (size_t)r); dlen += (size_t)r;
        }
        close(rfd);
    }
    unlink(pipepath);
    free(pipepath);
    plugin_parent_env_restore();
    resume_curses();
    if (data && dlen >= 2) process_pipe_data(data, dlen);
    free(data);
}

static void run_plugin_by_value(const char *value,
                                const char *arg_name, const char *arg_dir,
                                const char *nnnval)
{
    if (!value || !*value) return;
    if (value[0] == '!') {
        run_plugin_cmd(value + 1, true, arg_name, arg_dir, nnnval);
        return;
    }
    const char *name = value;
    if (name[0] == '-') name++;
    char *script;
    if (is_abs_path(name)) script = xstrdup(name);
    else script = join_path(G.pluginsdir, name);
    if (access(script, X_OK) != 0) { free(script); return; }
    run_plugin_cmd(script, false, arg_name, arg_dir, nnnval);
    free(script);
}
