actions.command:
cat >> nnn.c <<'EOF'

/* ------------------------------------------------------------------ */
/* contexts                                                             */

static void apply_cli_sort(Context *c)
{
    switch (gcfg.sort_key0) {
    case 'a': c->detail = DETAIL_AU; c->sort = SORT_SIZE; break;
    case 'd': c->detail = DETAIL_DU; c->sort = SORT_SIZE; break;
    case 'e': c->sort = SORT_EXT; break;
    case 'r': c->reverse = true; break;
    case 's': c->sort = SORT_SIZE; break;
    case 't': c->sort = SORT_TIME; break;
    case 'v': c->vermod = true; break;
    default: break;
    }
}
static void ctx_defaults(Context *c, Context *src, const char *path)
{
    memset(c, 0, sizeof *c);
    c->active = true;
    c->path = xstrdup(path);
    c->filter = xstrdup("");
    c->icase = true;
    if (src) {
        c->sort = src->sort; c->vermod = src->vermod; c->reverse = src->reverse;
        c->timetype = src->timetype; c->detail = src->detail;
        c->hidden = src->hidden; c->tty_nav = src->tty_nav;
        c->ftype = src->ftype; c->icase = src->icase;
        if (src->lastfilter) c->lastfilter = xstrdup(src->lastfilter);
    } else {
        c->detail = gcfg.detail0 ? DETAIL_FULL : DETAIL_LIGHT;
        c->hidden = gcfg.hidden0;
        c->tty_nav = gcfg.tty_nav0;
        c->ftype = gcfg.regex_filter0 ? FILTER_REG : gcfg.fuzzy0 ? FILTER_FZY : FILTER_STR;
        apply_cli_sort(c);
    }
}
static void save_current_hover(void)
{
    Context *c = CTX();
    free(c->hover);
    c->hover = cur_entry() ? xstrdup(cur_entry()->name) : NULL;
}
static int count_active(void)
{
    int n = 0;
    for (int i = 0; i < MAX_CTX; i++) if (ctxs[i].active) n++;
    return n;
}
static bool switch_context(int target)
{
    if (target < 0 || target >= MAX_CTX || target == curctx) return false;
    char *oldpath = xstrdup(CTX()->path);
    save_current_hover();
    free_entries();
    int old = curctx;
    curctx = target;
    if (!ctxs[target].active) {
        ctx_defaults(&ctxs[target], &ctxs[old], oldpath);
        /* a brand new context starts on the first entry */
        ctxs[target].cur = 0;
    }
    free(oldpath);
    ui_filter_prompt = false;
    load_dir(CTX()->hover);
    if (CTX()->tty_nav) ui_filter_prompt = true;
    return true;
}
static void cycle_context_tab(void)
{
    if (count_active() < 2) {
        for (int i = 1; i <= MAX_CTX; i++) {
            int t = (curctx + i) % MAX_CTX;
            if (!ctxs[t].active) { switch_context(t); return; }
        }
        return;
    }
    for (int i = 1; i <= MAX_CTX; i++) {
        int t = (curctx + i) % MAX_CTX;
        if (ctxs[t].active) { switch_context(t); return; }
    }
}
static void new_context_shift_tab(void)
{
    for (int i = 0; i < MAX_CTX; i++) {
        if (!ctxs[i].active) { switch_context(i); return; }
    }
    /* all contexts in use: cycle backwards */
    for (int i = 1; i <= MAX_CTX; i++) {
        int t = (curctx - i + MAX_CTX * 2) % MAX_CTX;
        if (ctxs[t].active) { switch_context(t); return; }
    }
}

static void cleanup_exit(int code);

static bool quit_context(void)
{
    if (count_active() <= 1) { cleanup_exit(gcfg.picker_file ? 0 : 0); return true; }
    int leaving = curctx;
    int target = -1;
    for (int i = leaving - 1; i >= 0; i--) if (ctxs[i].active) { target = i; break; }
    if (target < 0) for (int i = MAX_CTX - 1; i > leaving; i--) if (ctxs[i].active) { target = i; break; }
    if (target < 0) return false;
    switch_context(target);
    ctx_free_fields(&ctxs[leaving]);
    if (ctxs[leaving].listdir) remove_list_dir(ctxs[leaving].listdir);
    return true;
}
static void quit_all(bool ask)
{
    if (ask && !gcfg.no_quit_confirm && count_active() > 1) {
        if (!confirm_prompt("Quit all contexts?")) return;
    }
    cleanup_exit(0);
}

/* For the pipe protocol: which context a command applies to. */
static int ctx_for_pipe(char spec)
{
    if (spec == '+') {
        for (int i = 1; i <= MAX_CTX; i++) {
            int t = (curctx + i) % MAX_CTX;
            if (!ctxs[t].active) { switch_context(t); return curctx; }
        }
        return curctx;
    }
    if (spec == '0') return curctx;
    if (spec >= '1' && spec <= '8') {
        int t = spec - '1';
        if (t != curctx) switch_context(t);
        return curctx;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* sorting / time menus, movement                                       */

static void resort_reload(void)
{
    char *h = cur_entry() ? xstrdup(cur_entry()->name) : NULL;
    load_dir(h);
    free(h);
}
static void op_sort_menu(void)
{
    int k = read_choice("'a'u/'d'u/'e'xt/'r'ev/'s'z/'t'm/'v'er/'c'lr/'^T'?");
    Context *c = CTX();
    if (k == ESC_KEY) return;
    switch (k) {
    case 'a': c->detail = DETAIL_AU; c->sort = SORT_SIZE; break;
    case 'd': c->detail = DETAIL_DU; c->sort = SORT_SIZE; break;
    case 'e': if (c->detail >= DETAIL_DU) c->detail = DETAIL_FULL; c->sort = SORT_EXT; c->vermod = false; break;
    case 'r': c->reverse = !c->reverse; break;
    case 's': if (c->detail >= DETAIL_DU) c->detail = DETAIL_FULL; c->sort = SORT_SIZE; break;
    case 't': if (c->detail >= DETAIL_DU) c->detail = DETAIL_FULL; c->sort = SORT_TIME; break;
    case 'v': c->vermod = !c->vermod; if (c->detail >= DETAIL_DU) c->detail = DETAIL_FULL; break;
    case 'c': c->sort = SORT_NAME; c->vermod = false; c->reverse = false; if (c->detail >= DETAIL_DU) c->detail = DETAIL_FULL; break;
    case 20: /* ^T cycles name -> time -> size -> name */
        if (c->detail >= DETAIL_DU) c->detail = DETAIL_FULL;
        if (c->sort == SORT_TIME) c->sort = SORT_SIZE;
        else if (c->sort == SORT_SIZE) c->sort = SORT_NAME;
        else c->sort = SORT_TIME;
        break;
    default: set_msg("invalid key"); return;
    }
    resort_reload();
}
static void op_time_menu(void)
{
    Context *c = CTX();
    char cur = c->timetype == TIME_ACCESS ? 'a' : c->timetype == TIME_CHANGE ? 'c' : 'm';
    char prompt[64];
    snprintf(prompt, sizeof prompt, "'a'ccess / 'c'hange / 'm'od [%c]", cur);
    int k = read_choice(prompt);
    if (k == 'a') c->timetype = TIME_ACCESS;
    else if (k == 'c') c->timetype = TIME_CHANGE;
    else if (k == 'm') c->timetype = TIME_MOD;
    else if (k == ESC_KEY) return;
    else { set_msg("invalid key"); return; }
    if (c->sort == SORT_TIME) resort_reload();
}

static void move_cursor_delta(int delta)
{
    Context *c = CTX();
    if (!nview) return;
    int cur = c->cur + delta;
    if (cur >= nview) cur = gcfg.no_rollover ? nview - 1 : 0;
    if (cur < 0) cur = gcfg.no_rollover ? 0 : nview - 1;
    c->cur = cur;
}
static void page_move(int dir)
{
    Context *c = CTX();
    if (!nview) return;
    int pg = page_rows();
    int step = pg - 1; if (step < 1) step = 1;
    int maxoff = nview > pg ? nview - pg : 0;
    if (dir > 0) {
        c->off += step; if (c->off > maxoff) c->off = maxoff;
        c->cur += step; if (c->cur >= nview) c->cur = nview - 1;
    } else {
        c->off -= step; if (c->off < 0) c->off = 0;
        c->cur -= step; if (c->cur < 0) c->cur = 0;
    }
}

/* FIFO notification tracking */
static char *last_fifo_path = NULL;
static void notify_fifo_current(bool force)
{
    if (!G.fifo_path) return;
    Entry *e = cur_entry();
    if (!e) return;
    char *p = entry_path(e);
    if (force || !last_fifo_path || strcmp(last_fifo_path, p)) {
        fifo_notify(p);
        free(last_fifo_path); last_fifo_path = xstrdup(p);
    }
    free(p);
}
static void set_x_title(void)
{
    if (!gcfg.xflags) return;
    char host[256] = "";
    gethostname(host, sizeof host - 1);
    fprintf(stdout, "\033]7;file://%s%s\033\\", host, CTX()->path);
    fprintf(stdout, "\033]2;%s\007", CTX()->path);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* startup helpers                                                      */

static char *initial_hover = NULL;
static void atexit_title_restore(void)
{
    if (gcfg.xflags) { fputs("\033[23;0t", stdout); fflush(stdout); }
}

static void ensure_cfgdirs(void)
{
    mkdir_p(G.cfgdir);
    mkdir_p(G.sessionsdir);
    mkdir_p(G.bookmarksdir);
    mkdir_p(G.pluginsdir);
    mkdir_p(G.mountsdir);
}

static char *existing_ancestor(const char *absd, char **firstcomp)
{
    char *path = xstrdup(absd);
    for (;;) {
        struct stat st;
        if (stat(path, &st) == 0 && S_ISDIR(st.st_mode)) break;
        char *par = dir_name_dup(path);
        if (!strcmp(par, path)) { free(par); break; }
        free(path); path = par;
    }
    if (firstcomp) {
        size_t pl = strlen(path);
        const char *rel = absd + pl;
        if (*rel == '/') rel++;
        const char *slash = strchr(rel, '/');
        *firstcomp = slash ? xstrndup(rel, (size_t)(slash - rel)) : xstrdup(rel);
    }
    return path;
}

/* ------------------------------------------------------------------ */
/* main                                                                 */

static bool g_session_autosave = false;
static time_t last_activity = 0;
static struct timespec last_esc_ts;

static double ts_diff_ms(struct timespec a, struct timespec b)
{
    return (a.tv_sec - b.tv_sec) * 1000.0 + (a.tv_nsec - b.tv_nsec) / 1e6;
}

static void toggle_selection_current(void)
{
    Entry *e = cur_entry();
    if (!e) return;
    char *p = entry_path(e);
    int si = sel_index(p);
    if (si >= 0) sel_remove_at(si);
    else sel_add(p);
    e->selected = si < 0;
    free(p);
    sel_write_file();
    sel_sync_flags();
    if (!gcfg.noadvance) move_cursor_delta(1 > 0 && CTX()->cur + 1 < nview ? 1 : 0);
}
static void select_all(bool invert)
{
    for (int i = 0; i < nview; i++) {
        char *p = join_path(CTX()->path, view[i]->name);
        int si = sel_index(p);
        if (invert) {
            if (si >= 0) sel_remove_at(si); else sel_add(p);
        } else if (si < 0) sel_add(p);
        free(p);
    }
    sel_write_file();
    sel_sync_flags();
}
static void range_select(void)
{
    Context *c = CTX();
    Entry *e = cur_entry();
    if (!e) return;
    if (!c->range_anchor) {
        c->range_anchor = xstrdup(e->name);
        return;
    }
    int a = find_in_view(c->range_anchor);
    free(c->range_anchor); c->range_anchor = NULL;
    if (a < 0) return;
    int lo = a < c->cur ? a : c->cur, hi = a < c->cur ? c->cur : a;
    for (int i = lo; i <= hi; i++) {
        char *p = join_path(c->path, view[i]->name);
        if (sel_index(p) < 0) sel_add(p);
        free(p);
    }
    sel_write_file();
    sel_sync_flags();
}

static void refresh_if_changed(void)
{
#ifdef __linux__
    if (inotify_fd < 0) return;
    char buf[4096];
    bool changed = false;
    for (;;) {
        ssize_t r = read(inotify_fd, buf, sizeof buf);
        if (r > 0) { changed = true; continue; }
        break;
    }
    if (changed) {
        /* ignore changes caused by our own selection/tmp writes elsewhere */
        char *h = cur_entry() ? xstrdup(cur_entry()->name) : NULL;
        load_dir(h);
        free(h);
    }
#endif
}

static void cleanup_exit(int code)
{
    if (g_picker_pick_and_exit) code = 0;
    endwin();
    /* persistent session */
    if (g_session_autosave) session_save("@");
    if (gcfg.picker_file) {
        if (!strcmp(gcfg.picker_file, "-")) {
            char sep = gcfg.picker_null ? '\0' : '\n';
            for (int i = 0; i < nsel; i++) { fputs(sel[i], stdout); fputc(sep, stdout); }
            fflush(stdout);
        } else if (G.selpath) {
            FILE *f = fopen(G.selpath, "wb");
            if (f) {
                for (int i = 0; i < nsel; i++) {
                    fputs(sel[i], f);
                    fputc(gcfg.picker_null ? '\0' : '\n', f);
                }
                fclose(f);
            }
        }
    } else if (G.selpath) {
        unlink(G.selpath);
    }
    if (gcfg.autofifo && G.fifo_path) unlink(G.fifo_path);
    exit(code);
}

static void quitcd(void)
{
    const char *tf = getenv("NNN_TMPFILE");
    const char *dest = (tf && *tf) ? tf : G.lastdpath;
    if (dest) {
        int fd = open(dest, O_WRONLY | O_CREAT | O_TRUNC, 0600);
        if (fd >= 0) {
            dprintf(fd, "cd '%s'", CTX()->path);
            close(fd);
        }
    }
    cleanup_exit(0);
}

int main(int argc, char *argv[])
{
    setlocale(LC_ALL, "");
    memset(&gcfg, 0, sizeof gcfg);
    gcfg.scroll_lines = 0;
    gcfg.fifo_mode = 0;
    signal(SIGPIPE, SIG_IGN);
    /* ---- NNN_OPTS ---- */
    const char *nopts = getenv("NNN_OPTS");
    if (nopts) {
        for (const char *p = nopts; *p; p++) {
            if (!strchr(VALID_OPTS, *p)) { print_usage(); return 1; }
            bool ex = false;
            int rc = apply_option(*p, NULL, &ex);
            if (ex) return rc;
        }
    }
    /* ---- command line ---- */
    int opt;
    while ((opt = getopt(argc, argv, "aAb:BcCdDeEfF:gHiJKl:nNop:P:QrRs:St:T:uUVxz0h")) != -1) {
        bool ex = false;
        int rc = apply_option(opt, optarg, &ex);
        if (ex) return rc;
        if (opt == '?') { print_usage(); return 1; }
    }
    if (optind < argc) prog_path_option = argv[optind];
    atexit(atexit_title_restore);

    /* ---- stdin list input ---- */
    char **list_paths = NULL;
    int nlist = 0;
    bool have_list = false;
    if (!isatty(STDIN_FILENO)) {
        size_t cap = 8192, len = 0;
        char *data = xmalloc(cap);
        for (;;) {
            if (len == cap) { cap *= 2; data = xrealloc(data, cap); }
            ssize_t r = read(STDIN_FILENO, data + len, cap - len);
            if (r < 0) { if (errno == EINTR) continue; break; }
            if (r == 0) break;
            len += (size_t)r;
        }
        if (len == 0) {
            fputs("0 entries\n", stderr);
            free(data);
            return 1;
        }
        have_list = true;
        size_t start = 0; int capn = 0;
        for (size_t i = 0; i <= len; i++) {
            if (i == len || data[i] == '\0') {
                if (i > start) {
                    if (nlist == capn) { capn = capn ? capn * 2 : 16; list_paths = xrealloc(list_paths, (size_t)capn * sizeof *list_paths); }
                    list_paths[nlist++] = xstrndup(data + start, i - start);
                }
                start = i + 1;
            }
        }
        free(data);
        int ttyfd = open("/dev/tty", O_RDWR);
        if (ttyfd >= 0) { dup2(ttyfd, STDIN_FILENO); if (ttyfd > 2) close(ttyfd); }
    }

    /* ---- environment / configuration ---- */
    const char *home = getenv("HOME");
    if (!home || !*home) {
        struct passwd *pw = getpwuid(getuid());
        home = pw ? pw->pw_dir : "/";
    }
    G.home = xstrdup(home);
    const char *xdg = getenv("XDG_CONFIG_HOME");
    char *cfgbase;
    if (xdg && *xdg) cfgbase = xstrdup(xdg);
    else { cfgbase = join_path(G.home, ".config"); }
    G.cfgdir = join_path(cfgbase, "nnn");
    free(cfgbase);
    G.sessionsdir = join_path(G.cfgdir, "sessions");
    G.bookmarksdir = join_path(G.cfgdir, "bookmarks");
    G.pluginsdir = join_path(G.cfgdir, "plugins");
    G.mountsdir = join_path(G.cfgdir, "mounts");
    G.lastdpath = join_path(G.cfgdir, ".lastd");
    G.historypath = join_path(G.cfgdir, ".history");
    const char *tmpdir = getenv("TMPDIR");
    G.tmpdir = xstrdup(tmpdir && *tmpdir ? tmpdir : "/tmp");
    const char *shell = getenv("SHELL");
    G.shell = (shell && *shell) ? xstrdup(shell) : NULL;
    const char *pager = getenv("PAGER");
    G.pager = (pager && *pager) ? xstrdup(pager) : NULL;
    const char *opener = getenv("NNN_OPENER");
    G.opener = (opener && *opener) ? xstrdup(opener) : NULL;
    G.trash_set = getenv("NNN_TRASH") != NULL;
    G.trash_mode = G.trash_set ? atoi(getenv("NNN_TRASH")) : 0;
    const char *lvl = getenv("NNNLVL");
    G.nnnlvl = lvl ? atol(lvl) : 0;
    if (gcfg.picker_file && strcmp(gcfg.picker_file, "-")) {
        G.selpath = abs_path(gcfg.picker_file);
        unlink(G.selpath);
    } else {
        const char *sel = getenv("NNN_SEL");
        G.selpath = (sel && *sel) ? xstrdup(sel) : join_path(G.cfgdir, ".selection");
    }
    ensure_cfgdirs();
    if (gcfg.history) {
        int fd = open(G.historypath, O_WRONLY | O_CREAT | O_APPEND, 0600);
        if (fd >= 0) close(fd);
    }
    /* context colours */
    for (int i = 0; i < MAX_CTX; i++) G.ctxcolors[i] = 4;
    const char *ncolors = getenv("NNN_COLORS");
    G.have_ctxcolors_env = ncolors != NULL;
    if (ncolors) {
        for (int i = 0; i < MAX_CTX && ncolors[i]; i++)
            if (isdigit((unsigned char)ncolors[i]) && ncolors[i] <= '7') G.ctxcolors[i] = ncolors[i] - '0';
    }
    G.colors_on = !(getenv("NO_COLOR") != NULL && !G.have_ctxcolors_env);
    G.force_8color = gcfg.color8;
    const char *fcol = getenv("NNN_FCOLORS");
    if (fcol && (strlen(fcol) % 2)) { fputs("NNN_FCOLORS\n", stderr); return 1; }
    parse_fcolors();
    if (!parse_keyvals(getenv("NNN_BMS"), &bms, &nbms)) { fputs("NNN_BMS\n", stderr); return 1; }
    if (!parse_keyvals(getenv("NNN_PLUG"), &plugs, &nplugs)) { fputs("NNN_PLUG\n", stderr); return 1; }
    const char *archre = getenv("NNN_ARCHIVE");
    G.arch_regex_str = xstrdup(archre && *archre ? archre : "\\.(t?gz|t?bz2?|taz|tar|zip|z)$");
    if (regcomp(&G.arch_re, G.arch_regex_str, REG_EXTENDED | REG_ICASE | REG_NOSUB) != 0) {
        fputs("invalid regex\n", stderr);
        return 1;
    }
    G.arch_re_valid = true;
    /* FIFO */
    if (gcfg.autofifo) {
        if (asprintf(&G.fifo_path, "%s/nnn-fifo.%ld", G.tmpdir, (long)getpid()) < 0) G.fifo_path = NULL;
        if (G.fifo_path) {
            mkfifo(G.fifo_path, 0600);
            setenv("NNN_FIFO", G.fifo_path, 1);
        }
    } else {
        const char *fifo = getenv("NNN_FIFO");
        if (fifo && *fifo) {
            G.fifo_path = xstrdup(fifo);
            if (access(G.fifo_path, F_OK) != 0) mkfifo(G.fifo_path, 0600);
        }
    }
    /* bookmark key (checked before the UI starts) */
    char *bookmark_target = NULL;
    if (gcfg.bookmark_key) {
        const char *t = NULL;
        if (strlen(gcfg.bookmark_key) == 1) t = kv_find(bms, nbms, gcfg.bookmark_key[0]);
        if (!t) { fputs("invalid key\n", stderr); return 1; }
        bookmark_target = xstrdup(t);
    }

    /* ---- resolve the starting directory ---- */
    bool session_enabled = (gcfg.session_name || gcfg.persistent) && !prog_path_option && !bookmark_target && !have_list;
    const char *session_to_load = gcfg.persistent ? "@" : gcfg.session_name;
    bool have_session_file = false;
    if (session_enabled && session_to_load) {
        char *sp = join_path(G.sessionsdir, session_to_load);
        have_session_file = access(sp, F_OK) == 0;
        free(sp);
    }
    if (gcfg.persistent && session_enabled) g_session_autosave = true;
    char *initpath = NULL;
    char *listdir_created = NULL;
    if (have_list) {
        char *hov = NULL;
        if (!make_list_dir(list_paths, nlist, &listdir_created, &hov)) return 1;
        free(hov);
        initpath = xstrdup(listdir_created);
    } else if (!have_session_file || !session_enabled) {
        const char *arg = bookmark_target ? bookmark_target : (prog_path_option ? prog_path_option : ".");
        if (!arg || !*arg) arg = ".";
        char *absd = abs_path(arg);
        struct stat st;
        if (stat(absd, &st) == 0) {
            if (S_ISDIR(st.st_mode)) {
                /* fall back to the parent when the directory cannot
                 * be opened (matching start-up on an unreadable dir) */
                DIR *test = opendir(absd);
                if (test) { closedir(test); initpath = absd; }
                else {
                    initpath = dir_name_dup(absd);
                    initial_hover = xstrdup(base_name(absd));
                    free(absd);
                }
            } else {
                initial_hover = xstrdup(base_name(absd));
                initpath = dir_name_dup(absd);
                free(absd);
            }
        } else if (arg[strlen(arg) - 1] == '/') {
            if (mkdir_p(absd) != 0) {
                fprintf(stderr, "9832: %s\n", strerror(errno));
                return 1;
            }
            initpath = absd;
        } else {
            char *par = dir_name_dup(absd);
            if (mkdir_p(par) == 0) {
                initpath = par;
                pending_create = xstrdup(base_name(absd));
            } else {
                int e = errno;
                char *first = NULL;
                initpath = existing_ancestor(absd, &first);
                pending_create = first;
                startup_msg = xstrdup(strerror(e));
                free(par);
            }
            free(absd);
        }
    }
    free(bookmark_target);
    G.initpath = initpath ? xstrdup(initpath) : NULL;

    /* first context */
    curctx = 0;
    ctx_defaults(&ctxs[0], NULL, initpath ? initpath : ".");
    if (listdir_created) ctxs[0].listdir = xstrdup(listdir_created);

    /* ---- terminal ---- */
    if (gcfg.xflags) { fputs("\033[22;0t", stdout); fflush(stdout); }
    if (!initscr()) return 1;
    raw();
    noecho();
    curs_set(0);
    keypad(stdscr, TRUE);
    meta(stdscr, TRUE);
    set_escdelay(25);
    mousemask(ALL_MOUSE_EVENTS | REPORT_MOUSE_POSITION, NULL);
    mouseinterval(0);
    signal(SIGINT, SIG_IGN);
    signal(SIGQUIT, SIG_IGN);
    init_colours();
    timeout(100);

    bool loaded_session = false;
    if (have_session_file && session_enabled) {
        loaded_session = session_load(session_to_load);
        if (loaded_session) {
            free(G.initpath);
            G.initpath = xstrdup(CTX()->path);
        }
    }
    if (!loaded_session) {
        if (!load_dir(initial_hover)) {
            /* try the current directory as a last resort */
            free(CTX()->path);
            char cwd[PATH_MAX];
            CTX()->path = getcwd(cwd, sizeof cwd) ? xstrdup(cwd) : xstrdup("/");
            load_dir(NULL);
        }
    }
    fprintf(stdout, ""); /* keeps -O2 from warning about unused result paths */
    set_x_title();
    if (startup_msg) { set_msg(startup_msg); }
    if (CTX()->tty_nav) ui_filter_prompt = true;
    last_activity = time(NULL);
    memset(&last_esc_ts, 0, sizeof last_esc_ts);
    draw();
    notify_fifo_current(true);
    if (pending_create) {
        char *pc = pending_create; pending_create = NULL;
        op_create(pc);
        free(pc);
    }
    if (gcfg.plugin_key && strlen(gcfg.plugin_key) == 1) {
        run_plugin_key(gcfg.plugin_key[0]);
    }

    /* ---- main loop ---- */
    bool filter_ever = ui_filter_prompt;
    (void)filter_ever;
    while (!g_quit_all && !g_picker_pick_and_exit) {
        if (ui_filter_prompt) {
            /* sync the line-input widgets with the context filter */
            ui_kind = UI_FILTER;
            free(ui_prompt);
            ui_prompt = xstrdup(CTX()->ftype == FILTER_REG ? "\\" : "/");
            size_t need = mbstowcs(NULL, CTX()->filter, 0);
            free(ui_input);
            ui_input = xmalloc(((need == (size_t)-1 ? 0 : need) + 1) * sizeof(wchar_t));
            if (need == (size_t)-1) ui_input[0] = 0; else mbstowcs(ui_input, CTX()->filter, need + 1);
            ui_cursor = (int)wcslen(ui_input);
        } else ui_kind = UI_STATUS;
        draw();
        int k = get_key(NULL);
        if (k == ERR) {
            refresh_if_changed();
            if (gcfg.lock_secs > 0 && time(NULL) - last_activity >= gcfg.lock_secs) {
                op_lock();
                last_activity = time(NULL);
            }
            continue;
        }
        last_activity = time(NULL);
        struct timespec now_ts; clock_gettime(CLOCK_MONOTONIC, &now_ts);
        if (g_msg) { free(g_msg); g_msg = NULL; }
        Context *c = CTX();

        /* ---------- filter prompt handling ---------- */
        if (ui_filter_prompt) {
            bool consumed = true;
            bool exit_filter = false;
            bool do_open = false;
            if (k == KEY_ALT_ESC) {
                /* unfilter and quit the context */
                c = CTX();
                if (c->filter && *c->filter) { free(c->lastfilter); c->lastfilter = xstrdup(c->filter); }
                free(c->filter); c->filter = xstrdup("");
                c->filtered = false;
                set_base_to_all();
                rebuild_view();
                ui_filter_prompt = false;
                quit_context();
                continue;
            }
            if (k == ESC_KEY) { exit_filter = true; }
            else if (k == '\n' || k == '\r' || k == KEY_ENTER) { exit_filter = true; do_open = true; }
            else if (k == 12) { /* ^L: swap with the last filter */
                char *tmpf = c->lastfilter ? c->lastfilter : xstrdup("");
                c->lastfilter = xstrdup(c->filter);
                free(c->filter); c->filter = tmpf;
                rebuild_view();
            } else if (k == '/') {
                c->ftype = (c->ftype + 1) % 3;
                rebuild_view();
            } else if (k == ':' && (!c->filter || !*c->filter)) {
                c->icase = !c->icase;
                rebuild_view();
            } else if (k == 14) { /* ^N toggles type-to-nav (handled below) */
                consumed = false;
            } else if (k == KEY_BACKSPACE || k == 127 || k == 8) {
                size_t L = strlen(c->filter);
                if (L) {
                    /* drop the last UTF-8 character */
                    size_t i = L - 1;
                    while (i > 0 && (c->filter[i] & 0xC0) == 0x80) i--;
                    c->filter[i] = 0;
                }
                rebuild_view();
            } else if (k == 21) { /* ^U clear */
                c->filter[0] = 0; rebuild_view();
            } else if (k >= 32 && k < KEY_MIN) {
                char mb[8];
                wint_t wc = (wint_t)k;
                int mbl = wctomb(mb, (wchar_t)wc);
                if (mbl < 0) { mb[0] = (char)k; mbl = 1; }
                size_t L = strlen(c->filter);
                c->filter = xrealloc(c->filter, L + (size_t)mbl + 1);
                memcpy(c->filter + L, mb, (size_t)mbl); c->filter[L + (size_t)mbl] = 0;
                rebuild_view();
                if (!gcfg.noautoenter && nview == 1 && view[0]->is_dir) {
                    char *absd = entry_path(view[0]);
                    ui_filter_prompt = false;
                    free(c->filter); c->filter = xstrdup("");
                    c->filtered = false;
                    change_dir_abs(abs_path(absd), NULL);
                    free(absd);
                    if (CTX()->tty_nav) ui_filter_prompt = true;
                    notify_fifo_current(false);
                    continue;
                }
                if (nview) c->cur = 0;
            } else {
                consumed = false; /* navigation/command keys fall through */
            }
            if (consumed) {
                if (exit_filter) {
                    if (c->filter && *c->filter) {
                        free(c->lastfilter); c->lastfilter = xstrdup(c->filter);
                        set_base_to_view();
                        c->filtered = true;
                    }
                    ui_filter_prompt = false;
                    if (do_open && cur_entry()) {
                        if (selecting_plugin && plugin_select_open(cur_entry())) { }
                        else op_open_entry(cur_entry(), true);
                    }
                }
                notify_fifo_current(false);
                continue;
            }
            /* fall through: leave the filter prompt (applying it) and
             * process the key as a normal command. */
            if (c->filter && *c->filter) {
                free(c->lastfilter); c->lastfilter = xstrdup(c->filter);
                set_base_to_view();
                c->filtered = true;
            }
            ui_filter_prompt = false;
        }

        /* ---------- main keys ---------- */
        Entry *e = cur_entry();
        if (k >= KEY_ALT_BASE && k != KEY_ALT_ENTER && k != KEY_ALT_ESC) {
            set_msg("invalid key");
            continue;
        }
        switch (k) {
        case ESC_KEY: {
            if (last_esc_ts.tv_sec && ts_diff_ms(now_ts, last_esc_ts) < 1000) {
                last_esc_ts = now_ts;
                quit_all(true);
                break;
            }
            last_esc_ts = now_ts;
            notify_fifo_current(true);
            break; }
        case KEY_ALT_ESC:
            break;
        case KEY_ALT_ENTER:
            op_select_plugin();
            break;
        case KEY_MOUSE: {
            MEVENT ev;
            if (getmouse(&ev) == OK) {
                if (ev.bstate & BUTTON4_PRESSED) {
                    int n = gcfg.scroll_lines > 0 ? (int)gcfg.scroll_lines : 3;
                    while (n-- > 0) move_cursor_delta(-1);
                } else if (ev.bstate & BUTTON5_PRESSED) {
                    int n = gcfg.scroll_lines > 0 ? (int)gcfg.scroll_lines : 3;
                    while (n-- > 0) move_cursor_delta(1);
                } else if (ev.bstate & (BUTTON1_CLICKED | BUTTON1_DOUBLE_CLICKED)) {
                    int idx = c->off + (ev.y - 2);
                    if (ev.y >= 2 && idx >= 0 && idx < nview) {
                        if (ev.bstate & BUTTON1_DOUBLE_CLICKED) {
                            c->cur = idx;
                            e = cur_entry();
                            if (e) { if (selecting_plugin && plugin_select_open(e)) { } else op_open_entry(e, true); }
                        } else c->cur = idx;
                    }
                } else if (ev.bstate & BUTTON3_CLICKED) {
                    /* right click: parent directory */
                    if (strcmp(c->path, "/") != 0) {
                        char *par = dir_name_dup(c->path);
                        char *hov = xstrdup(base_name(c->path));
                        change_dir_abs(par, hov);
                        free(hov);
                    }
                }
            }
            break; }
        case KEY_RESIZE:
            break;
        case KEY_UP: case 'k':
            move_cursor_delta(-1); break;
        case KEY_DOWN: case 'j':
            move_cursor_delta(1); break;
        case KEY_PPAGE: case 21:
            page_move(-1); break;
        case KEY_NPAGE: case 4:
            page_move(1); break;
        case KEY_HOME: case 'g': case 1:
            c->cur = 0; break;
        case KEY_END: case 'G': case 5:
            c->cur = nview ? nview - 1 : 0; break;
        case KEY_LEFT: case 'h':
            if (strcmp(c->path, "/") != 0) {
                char *par = dir_name_dup(c->path);
                char *hov = xstrdup(base_name(c->path));
                change_dir_abs(par, hov);
                free(hov);
            }
            break;
        case KEY_RIGHT: case 'l':
            if (e) { if (selecting_plugin && plugin_select_open(e)) { } else op_open_entry(e, false); }
            break;
        case '\r': case KEY_ENTER:
            if (e) {
                if (selecting_plugin && plugin_select_open(e)) { }
                else {
                    bool was_file = !e->is_dir;
                    op_open_entry(e, true);
                    if (was_file && g_autoadvance && CTX()->cur + 1 < nview) CTX()->cur++;
                }
            }
            break;
        case '\n': /* ^J */
            g_autoadvance = !g_autoadvance;
            break;
        case '~':
            change_dir_abs(xstrdup(G.home), NULL); break;
        case '`':
            change_dir_abs(xstrdup("/"), NULL); break;
        case '@':
            if (G.initpath) change_dir_abs(xstrdup(G.initpath), NULL); break;
        case '-':
            if (c->lastdir) change_dir_abs(xstrdup(c->lastdir), NULL);
            else set_msg("not set");
            break;
        case '\'': {
            int kk = read_choice("first file (')/char?");
            if (kk == '\'') {
                for (int i = 0; i < nview; i++) if (!view[i]->is_dir) { c->cur = i; break; }
            } else if (kk > 0 && kk < 256) {
                for (int i = 0; i < nview; i++) if (view[i]->name[0] == (char)kk) { c->cur = i; break; }
            }
            break; }
        case 'J': {
            ui_jump = true;
            char *inp = read_line("jump (+n/-n/n): ", "");
            ui_jump = false;
            if (inp && *inp && nview) {
                char *end = NULL;
                long v = strtol(inp, &end, 10);
                if (end && *end == 0) {
                    if (inp[0] == '+' || inp[0] == '-') {
                        int t = c->cur + (int)v;
                        if (t >= 0 && t < nview) c->cur = t;
                    } else {
                        int t = (int)v - 1;
                        if (t >= 0 && t < nview) c->cur = t;
                    }
                }
            }
            free(inp);
            break; }
        case 25: /* ^Y: next young */
            if (nview) {
                for (int step = 1; step <= nview; step++) {
                    int idx = (c->cur + step) % nview;
                    if (entry_young(view[idx])) { c->cur = idx; break; }
                }
            }
            break;
        case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8':
            switch_context(k - '1');
            break;
        case '\t':
            cycle_context_tab();
            break;
        case KEY_BTAB:
            new_context_shift_tab();
            break;
        case 'q':
            quit_context();
            break;
        case 'Q':
            cleanup_exit(1);
            break;
        case 17: /* ^Q */
            quit_all(true);
            break;
        case 7: /* ^G */
            quitcd();
            break;
        case 12: /* ^L */
            if (c->filtered) {
                if (c->filter && *c->filter) { free(c->lastfilter); c->lastfilter = xstrdup(c->filter); }
                free(c->filter); c->filter = xstrdup("");
                c->filtered = false;
                set_base_to_all();
                rebuild_view();
            } else {
                clearok(stdscr, TRUE);
                char *h = e ? xstrdup(e->name) : NULL;
                load_dir(h);
                free(h);
            }
            break;
        case 14: /* ^N */
            c->tty_nav = !c->tty_nav;
            if (c->tty_nav) {
                ui_filter_prompt = true;
            } else {
                ui_filter_prompt = false;
                free(c->filter); c->filter = xstrdup("");
                c->filtered = false;
                set_base_to_all();
                rebuild_view();
            }
            break;
        case '/':
            ui_filter_prompt = true;
            free(c->filter); c->filter = xstrdup("");
            rebuild_view();
            break;
        case '.':
            c->hidden = !c->hidden;
            {
                char *h = e ? xstrdup(e->name) : NULL;
                c->filtered = false;
                if (c->filter) c->filter[0] = 0;
                load_dir(h);
                free(h);
                if (c->tty_nav) ui_filter_prompt = true;
            }
            break;
        case 'd':
            if (c->detail >= DETAIL_DU) {
                c->detail = DETAIL_LIGHT;
                c->sort = SORT_NAME;
                resort_reload();
            } else if (c->detail == DETAIL_FULL) c->detail = DETAIL_LIGHT;
            else c->detail = DETAIL_FULL;
            break;
        case 't': case 20:
            op_sort_menu(); break;
        case 'T':
            op_time_menu(); break;
        case 'o': case 15:
            op_open_with(); break;
        case 'f': case 6:
            op_file_stats(); break;
        case 18: /* ^R */
            op_rename(); break;
        case 'r':
            op_batch_rename(); break;
        case 'z':
            op_archive_create(); break;
        case 'e':
            if (e && !e->is_dir) {
                char *p = entry_path(e);
                edit_file(p, false);
                free(p);
                after_op_reload(e->name);
            }
            break;
        case '*':
            op_toggle_exe(); break;
        case '>':
            op_export_list(); break;
        case ' ': case '+':
            toggle_selection_current(); break;
        case 'm':
            range_select(); break;
        case 'a':
            select_all(false); break;
        case 'A':
            select_all(true); break;
        case 'p': case 16:
            op_copy_move_here(false); break;
        case 'v': case 22:
            op_copy_move_here(true); break;
        case 'w': case 23:
            op_copy_move_as(); break;
        case 'x': case 24:
            op_delete(false); break;
        case 'X':
            op_delete(true); break;
        case 'E':
            op_edit_selection(); break;
        case 'S':
            op_listed_sel_size(); break;
        case 'n':
            op_create(NULL); break;
        case ';':
            op_plugin_prompt(); break;
        case '=':
            op_launch_app(); break;
        case '!': case 29:
            op_shell(); break;
        case ']':
            op_cmd_prompt(); break;
        case 'c':
            op_connect_remote(); break;
        case 'u':
            op_unmount(); break;
        case 's':
            op_session(); break;
        case '0':
            op_lock(); break;
        case '?':
            op_help(); break;
        case 'B':
            op_add_bookmark(); break;
        case ',':
            op_mark_dir(); break;
        case 'b': case 31:
            op_select_bookmark(); break;
        default:
            break;
        }
        if (!g_quit_all && !g_picker_pick_and_exit) {
            set_x_title();
            notify_fifo_current(false);
        }
    }
    cleanup_exit(g_exit_code);
    return 0;
}
