p='nnn.c'; s=open(p).read()
s=s.replace("    bool have_list = false;", "    bool have_list = false;\n    bool list_no_tty = false;")
old="""        int ttyfd = open("/dev/tty", O_RDWR);
        if (ttyfd >= 0) { dup2(ttyfd, STDIN_FILENO); if (ttyfd > 2) close(ttyfd); }"""
new="""        int ttyfd = open("/dev/tty", O_RDWR);
        if (ttyfd >= 0) { dup2(ttyfd, STDIN_FILENO); if (ttyfd > 2) close(ttyfd); }
        else list_no_tty = true;"""
assert old in s; s=s.replace(old,new)
old2="""    init_colours();
    timeout(100);"""
new2="""    init_colours();
    timeout(100);
    if (list_no_tty) { endwin(); return 1; }"""
assert old2 in s; s=s.replace(old2,new2)
open(p,'w').write(s)
PY
./compile.sh 2>/tmp/build.log; echo $?
timeout 120 python3 /tmp/clitest.py

