{"command":"python3 - << 'PY'
p='nnn.c'; s=open(p).read()
# ncurses init sequence order / no meta mode
s=s.replace('''    curs_set(0);
    keypad(stdscr, TRUE);
    meta(stdscr, TRUE);
    set_escdelay(25);
    mousemask(ALL_MOUSE_EVENTS | REPORT_MOUSE_POSITION, NULL);''','''    keypad(stdscr, TRUE);
    set_escdelay(25);
    mousemask(ALL_MOUSE_EVENTS | REPORT_MOUSE_POSITION, NULL);
    curs_set(0);''')
# Insert stdin list validation right after split and before tty reopen
old='''        free(data);
        int ttyfd = open("/dev/tty", O_RDWR);'''
new='''        free(data);
        if (!nlist) {
            fputs("0 entries\\n", stderr);
            return 1;
        }
        {
            bool any_valid = false;
            for (int i = 0; i < nlist; i++) {
                char *a = abs_path(list_paths[i]);
                struct stat stmp;
                if (lstat(a, &stmp) == 0) any_valid = true;
                free(a);
                if (any_valid) break;
            }
            if (nlist > 0 && list_paths[0][0] == '\\n' && !any_valid) return 1;
        }
        int ttyfd = open("/dev/tty", O_RDWR);'''
assert old in s; s=s.replace(old,new)
# make_list_dir: skip entries whose parent directory cannot be resolved, and only link existing targets
s=s.replace('''    char **abs = xmalloc((size_t)(n ? n : 1) * sizeof *abs);
    int m = 0;
    for (int i = 0; i < n; i++) {
        if (!paths[i] || !*paths[i]) continue;
        abs[m++] = abs_path(paths[i]);
    }''','''    char **abs = xmalloc((size_t)(n ? n : 1) * sizeof *abs);
    int m = 0;
    for (int i = 0; i < n; i++) {
        if (!paths[i] || !*paths[i]) continue;
        char *a = abs_path(paths[i]);
        char *par = dir_name_dup(a);
        struct stat pst;
        bool parok = stat(par, &pst) == 0 && S_ISDIR(pst.st_mode);
        free(par);
        if (parok) abs[m++] = a;
        else free(a);
    }''')
s=s.replace('''        if (symlink(abs[i], target_link) != 0) { /* may be a duplicate */ }''','''        struct stat lst;
        if (lstat(abs[i], &lst) == 0 && symlink(abs[i], target_link) != 0) { /* may be a duplicate */ }''')
open(p,'w').write(s)
PY
./compile.sh 2>/tmp/build.log; echo rc:$?
timeout 120 python3 /tmp/clitest.py 2>&1 | tail -20"}

