                if (common[j] == '/') lastslash = j;
                j++;
            }
            if (common[j] || par[j]) {
                /* mismatch: keep the common complete components */
                if (!common[j] && par[j] == '/') {
                    /* common is a complete prefix of par: keep it */
                } else if (!par[j] && common[j] == '/') {
                    common[j] = 0;
