{"command":"python3 - << 'PY'
p='nnn.c'; s=open(p).read()
# Status helpers before draw_status
s=s.replace('''static void draw_status(void)
{''','''static void saddstr(const char *s)
{
    int rem = (COLS - 2) - getcurx(stdscr);
    if (rem > 0) addstr_trunc(s, rem);
}
static void saddch(int ch)
{
    if (getcurx(stdscr) < COLS - 2) addch((unsigned char)ch);
}
static void draw_status(void)
{''')
start=s.find('static void draw_status(void)')
end=s.find('\nstatic void draw(void)',start)
seg=s[start:end]
seg2=seg.replace('addstr_trunc(g_msg, COLS)','addstr_trunc(g_msg, COLS - 2)')
# replace addstr/addch but avoid saddstr already (helpers are before start), and addstr_trunc calls turn into saddstr_trunc accidentally; handle placeholders
seg2=seg2.replace('addstr_trunc','@@TRUNC@@')
seg2=seg2.replace('addstr(','saddstr(').replace('addch(','saddch(')
seg2=seg2.replace('@@TRUNC@@','addstr_trunc')
# DU segment trunc uses COLS-getcurx; change to limit expression
seg2=seg2.replace('addstr_trunc(tmp, COLS - getcurx(stdscr))','addstr_trunc(tmp, (COLS - 2) - getcurx(stdscr))')
seg2=seg2.replace('addstr_trunc(target, COLS - getcurx(stdscr))','addstr_trunc(target, (COLS - 2) - getcurx(stdscr))')
s=s[:start]+seg2+s[end:]
# fit display path in header
old='''        addch(' ');
        char *dp = display_path(c->path);
        attron(ctx_pair() | A_UNDERLINE);
        addstr_trunc(dp, COLS - getcurx(stdscr));
        attroff(ctx_pair() | A_UNDERLINE);
        free(dp);'''
new='''        addch(' ');
        char *dp = display_path(c->path);
        int avail = COLS - getcurx(stdscr);
        if (avail >= 2 && strwidth(dp) > avail) {
            /* Abbreviate every component but the last to its first
             * character (fish-style), then truncate to fit. */
            char *src = dp;
            char *out = xmalloc(strlen(src) + 1);
            size_t oi = 0;
            const char *pp = src;
            while (*pp) {
                const char *slash = strchr(pp, '/');
                if (!slash) { strcpy(out + oi, pp); oi += strlen(pp); break; }
                if (slash == pp) { out[oi++] = '/'; pp++; continue; }
                /* first character (one UTF-8 sequence) of this component */
                mbstate_t ps; memset(&ps, 0, sizeof ps);
                wchar_t wc; size_t r = mbrtowc(&wc, pp, MB_CUR_MAX, &ps);
                if (r == (size_t)-1 || r == (size_t)-2 || r == 0) r = 1;
                memcpy(out + oi, pp, r); oi += r;
                out[oi++] = '/';
                pp = slash + 1;
            }
            out[oi] = 0;
            free(dp); dp = out;
        }
        attron(ctx_pair() | A_UNDERLINE);
        if (avail >= 2) addstr_trunc(dp, avail);
        attroff(ctx_pair() | A_UNDERLINE);
        free(dp);'''
