{"command":"cat > /tmp/reinsert.c <<'EOF'
static char *read_line_native(const char *prompt);
static void op_open_with(void)
{
    Entry *e = cur_entry();
    if (!e) return;
    char *prog;
    if (gcfg.native_prompt) prog = read_line_hist("open with: ", "", true);
    else prog = read_line_native("open with: ");
    if (!prog || !*prog) { free(prog); return; }
    int k = read_choice("['g'ui]/'c'li?");
    if (k != 'g' && k != 'c' && k != '\n' && k != '\r' && k != KEY_ENTER) { free(prog); return; }
    char *path = entry_path(e);
    if (k == 'c') run_words_fg(prog, path, false);
    else run_detached_words(prog, path);
    free(path); free(prog);
    if (g_autoadvance && CTX()->cur + 1 < nview) CTX()->cur++;
}

static char *capture_cmd(char *const argv[])
{
    int pipefd[2];
    if (pipe(pipefd)) return xstrdup("");
    pid_t pid = fork();
    if (pid == 0) {
        dup2(pipefd[1], 1); dup2(pipefd[1], 2);
        close(pipefd[0]); close(pipefd[1]);
        execvp(argv[0], argv);
        _exit(127);
    }
    close(pipefd[1]);
    size_t cap = 8192, len = 0;
    char *buf = xmalloc(cap);
    for (;;) {
        if (len + 4096 >= cap) { cap *= 2; buf = xrealloc(buf, cap); }
        ssize_t r = read(pipefd[0], buf + len, cap - len - 1);
        if (r <= 0) break;
        len += (size_t)r;
    }
    close(pipefd[0]);
    int st; if (pid > 0) waitpid(pid, &st, 0);
    buf[len] = 0;
    return buf;
}
static void op_file_stats(void)
{
    if (!nview) return;
    int idx = CTX()->cur;
    int xoff = 0, yoff = 0;
    for (;;) {
        Entry *e = view[idx];
        char *path = entry_path(e);
        char *parts[3]; int np = 0;
        if (find_in_path("stat")) { char *a[] = {(char*)"stat", path, NULL}; parts[np++] = capture_cmd(a); }
        if (find_in_path("file")) {
            char *a[] = {(char*)"file", (char*)"-b", path, NULL}; parts[np++] = capture_cmd(a);
            char *b[] = {(char*)"file", (char*)"-biL", path, NULL}; parts[np++] = capture_cmd(b);
        }
        size_t tot = 1; for (int i = 0; i < np; i++) tot += strlen(parts[i]) + 1;
        char *text = xmalloc(tot); text[0] = 0;
        for (int i = 0; i < np; i++) { strcat(text, parts[i]); free(parts[i]); }
        char **lines = NULL; int nl = 0, cl = 0;
        char *save = NULL;
        for (char *tok = strtok_r(text, "\n", &save); tok; tok = strtok_r(NULL, "\n", &save)) {
            if (nl == cl) { cl = cl ? cl * 2 : 16; lines = xrealloc(lines, (size_t)cl * sizeof *lines); }
            lines[nl++] = tok;
        }
        int action = 0;
        for (;;) {
            draw();
            int h = LINES - 4; if (h > 20) h = 20; if (h < 4) h = LINES > 4 ? LINES : 4;
            int w = COLS * 3 / 4; if (w < 20) w = COLS; if (w > COLS) w = COLS;
            int y = (LINES - h) / 2; if (y < 0) y = 0;
            int x = (COLS - w) / 2; if (x < 0) x = 0;
            WINDOW *win = newwin(h, w, y, x);
            box(win, 0, 0);
            char title[128];
            snprintf(title, sizeof title, " %d/%d ", idx + 1, nview);
            wmove(win, 0, 2); waddstr(win, title);
            wattron(win, A_BOLD); waddstr(win, e->name); wattroff(win, A_BOLD);
            waddch(win, ' ');
            wmove(win, h - 1, 1);
            waddstr(win, "q/ESC:close  arrows:scroll  n/j:next  p/k:prev");
            int maxlen = 0;
            for (int i = 0; i < nl; i++) { int L = (int)strlen(lines[i]); if (L > maxlen) maxlen = L; }
            int textrows = h - 4;
            if (yoff > nl - 1) yoff = nl ? nl - 1 : 0;
            if (yoff < 0) yoff = 0;
            for (int i = 0; i < textrows && yoff + i < nl; i++) {
                wmove(win, 2 + i, 1);
                const char *ln = lines[yoff + i];
                if ((int)strlen(ln) > xoff) waddnstr(win, ln + xoff, w - 2);
            }
            if (maxlen - xoff > w - 2) mvwaddch(win, h - 2, w - 2, '>');
            if (xoff > 0) mvwaddch(win, h - 2, 1, '<');
            wrefresh(win);
            int k = get_key(NULL);
            delwin(win);
            touchwin(stdscr);
            if (k == 'q' || k == ESC_KEY) { action = 0; break; }
            if (k == 'n' || k == 'j') { if (idx + 1 < nview) { action = 1; } else { action = 0; } if (action) break; else continue; }
            if (k == 'p' || k == 'k') { if (idx > 0) { action = -1; break; } else continue; }
            if (k == KEY_DOWN) { if (yoff + textrows < nl) yoff++; continue; }
            if (k == KEY_UP) { if (yoff > 0) yoff--; continue; }
            if (k == KEY_RIGHT) { int mx = maxlen - (w - 2); if (mx < 0) mx = 0; xoff += 10; if (xoff > mx) xoff = mx; continue; }
            if (k == KEY_LEFT) { xoff -= 10; if (xoff < 0) xoff = 0; continue; }
            if (k == KEY_NPAGE) { yoff += textrows; if (yoff > nl - 1) yoff = nl ? nl - 1 : 0; continue; }
            if (k == KEY_PPAGE) { yoff -= textrows; if (yoff < 0) yoff = 0; continue; }
        }
        free(lines); free(text); free(path);
        if (action == 1) { idx++; xoff = yoff = 0; continue; }
        if (action == -1) { idx--; xoff = yoff = 0; continue; }
        break;
    }
}

