static void op_batch_rename(void)
{
    int src = choose_opsrc(true);
    if (src == OPSRC_NONE) return;
    char **oldnames = NULL, **oldpaths = NULL;
    int n = 0;
    if (src == OPSRC_CURRENT) {
        n = nview;
        oldnames = xmalloc((size_t)(n ? n : 1) * sizeof *oldnames);
        oldpaths = xmalloc((size_t)(n ? n : 1) * sizeof *oldpaths);
        for (int i = 0; i < n; i++) {
            oldnames[i] = xstrdup(view[i]->name);
            oldpaths[i] = entry_path(view[i]);
        }
    } else {
        bool borrowed = false;
        char **paths = effective_selection(&n, &borrowed);
        oldnames = xmalloc((size_t)(n ? n : 1) * sizeof *oldnames);
        oldpaths = xmalloc((size_t)(n ? n : 1) * sizeof *oldpaths);
        for (int i = 0; i < n; i++) {
            oldpaths[i] = xstrdup(paths[i]);
            oldnames[i] = xstrdup(paths[i]);
        }
        if (!borrowed) freev(paths, n);
    }
    if (!n) { free(oldnames); free(oldpaths); return; }
    char *tmp = make_tmpfile();
    if (!tmp) { freev(oldnames, n); freev(oldpaths, n); return; }
    FILE *f = fopen(tmp, "wb");
    if (f) { for (int i = 0; i < n; i++) fprintf(f, "%s\n", oldnames[i]); fclose(f); }
    char *oldhidden = getenv("NNN_INCLUDE_HIDDEN") ? xstrdup(getenv("NNN_INCLUDE_HIDDEN")) : NULL;
    char *oldpref = getenv("NNN_PREFER_SELECTION") ? xstrdup(getenv("NNN_PREFER_SELECTION")) : NULL;
    char *oldlist = getenv("NNN_LIST") ? xstrdup(getenv("NNN_LIST")) : NULL;
    setenv("NNN_INCLUDE_HIDDEN", CTX()->hidden ? "1" : "0", 1);
    setenv("NNN_PREFER_SELECTION", gcfg.use_selection ? "1" : "0", 1);
    setenv("NNN_LIST", CTX()->listdir ? CTX()->listdir : "", 1);
    edit_file(tmp, true);
    if (oldhidden) setenv("NNN_INCLUDE_HIDDEN", oldhidden, 1); else unsetenv("NNN_INCLUDE_HIDDEN");
    if (oldpref) setenv("NNN_PREFER_SELECTION", oldpref, 1); else unsetenv("NNN_PREFER_SELECTION");
    if (oldlist) setenv("NNN_LIST", oldlist, 1); else unsetenv("NNN_LIST");
    free(oldhidden); free(oldpref); free(oldlist);
    f = fopen(tmp, "rb");
    char **newnames = xmalloc((size_t)n * sizeof *newnames);
    for (int i = 0; i < n; i++) newnames[i] = NULL;
    if (f) {
        char *line = NULL; size_t lc = 0; int i = 0;
        while (i < n && getline(&line, &lc, f) > 0) {
            size_t L = strlen(line);
            while (L && (line[L-1] == '\n' || line[L-1] == '\r')) line[--L] = 0;
            newnames[i++] = xstrdup(line);
        }
        free(line); fclose(f);
    }
    unlink(tmp); free(tmp);
    char *hovername = cur_entry() ? xstrdup(cur_entry()->name) : NULL;
    for (int i = 0; i < n; i++) {
        if (!newnames[i] || !*newnames[i]) continue;
        if (!strcmp(newnames[i], oldnames[i])) continue;
        char *dest;
        if (src == OPSRC_SEL && is_abs_path(newnames[i])) dest = xstrdup(newnames[i]);
        else if (src == OPSRC_SEL) {
            char *par = dir_name_dup(oldpaths[i]);
            dest = join_path(par, newnames[i]); free(par);
        } else dest = is_abs_path(newnames[i]) ? xstrdup(newnames[i]) : join_path(CTX()->path, newnames[i]);
        if (strcmp(dest, oldpaths[i])) {
            char *a[] = {(char*)"mv", (char*)"-i", (char*)"--", oldnames[i], newnames[i], NULL};
            char *a2[] = {(char*)"mv", (char*)"-i", (char*)"--", oldpaths[i], dest, NULL};
            if (src == OPSRC_CURRENT) run_argv_fg(a, false, false);
            else run_argv_fg(a2, false, false);
        }
        free(dest);
    }
    freev(newnames, n); freev(oldnames, n); freev(oldpaths, n);
    if (src == OPSRC_SEL) sel_clear(true);
    after_op_reload(hovername);
    free(hovername);
}

static void op_edit_selection(void)
{
