    edit_file(tmp, true);
    sel_clear(false);
    f = fopen(tmp, "rb");
    if (f) {
        char *line = NULL; size_t lc = 0;
        while (getline(&line, &lc, f) > 0) {
            size_t L = strlen(line);
            while (L && (line[L-1] == '\n' || line[L-1] == '\r')) line[--L] = 0;
            if (*line) sel_add(line);
        }
        free(line); fclose(f);
    }
    unlink(tmp); free(tmp);
