p='nnn.c';s=open(p).read()
s=s.replace('''    raw();
    nonl();''','''    cbreak();
    nonl();''')
# ignore SIGTSTP at startup alongside existing INT/QUIT (where line is in main)
s=s.replace('''    signal(SIGINT, SIG_IGN);
    signal(SIGQUIT, SIG_IGN);''','''    signal(SIGINT, SIG_IGN);
    signal(SIGQUIT, SIG_IGN);
    signal(SIGTSTP, SIG_IGN);''')
# refactor quit_all signature/usages and quitcd
old='''static void quit_all(bool ask)
{
    if (ask && !gcfg.no_quit_confirm && count_active() > 1) {
        if (!confirm_prompt("Quit all contexts?")) return;
    }
    cleanup_exit(0);
}'''
new='''static void quit_all_code(bool ask, int code, bool write_cd)
{
    if (ask && !gcfg.no_quit_confirm && count_active() > 1) {
        if (!confirm_prompt("Quit all contexts?")) return;
    }
    if (write_cd) {
        const char *tf = getenv("NNN_TMPFILE");
        const char *dest = (tf && *tf) ? tf : G.lastdpath;
        if (dest) write_lastd_file(dest);
    }
    cleanup_exit(code);
}
static void quit_all(bool ask) { quit_all_code(ask, 0, false); }'''
# write_lastd_file defined later than quit_all - need forward? quit_all_code uses write_lastd_file defined near cleanup (later). Add forward declaration before quit_all_code via insertion in new text: declare above using a prototype line before function
new='''static void write_lastd_file(const char *dest);
'''+new
assert old in s; s=s.replace(old,new)
# Q case
s=s.replace('''        case 'Q':
            cleanup_exit(1);
            break;''','''        case 'Q':
            quit_all_code(true, 1, false);
            break;''')
# Ctrl-G case call quit_all_code instead quitcd()
s=s.replace('''        case 7: /* ^G */
            quitcd();
            break;''','''        case 7: /* ^G */
            quit_all_code(true, 0, true);
            break;''')
# quitcd() function now unused but keep (it may call cleanup)
open(p,'w').write(s)
