{"command":"python3 - << 'PY'
p='nnn.c';s=open(p).read()
# Add goto bookmark function after op_select_bookmark's goto_path call replacement: easiest add a new function before op_select_bookmark and change calls inside it.
s=s.replace('''static void op_select_bookmark(void)''','''static bool goto_bookmark_dir(const char *path)
{
    if (!path || !*path) return false;
    char *expanded;
    if (!strcmp(path, "~")) expanded = xstrdup(G.home);
    else if (path[0] == '~' && path[1] == '/') expanded = join_path(G.home, path + 2);
    else expanded = xstrdup(path);
    char *absd = abs_path(expanded);
    free(expanded);
    struct stat st;
    DIR *test = NULL;
    if (stat(absd, &st) != 0 || !S_ISDIR(st.st_mode) || !(test = opendir(absd))) {
        set_msg("dir inaccessible");
        free(absd);
        return false;
    }
    closedir(test);
    return change_dir_abs(absd, NULL);
}
static void op_select_bookmark(void)''')
# Within op_select_bookmark, replace goto_path(markdir/target) - there are 2 occurrences in that function, later goto_path definition and pipe uses should remain. Replace first two occurrences after the new function.
idx=s.find('static void op_select_bookmark')
seg=s[idx:idx+2500]
seg2=seg.replace('goto_path(markdir)','goto_bookmark_dir(markdir)').replace('goto_path(target)','goto_bookmark_dir(target)')
s=s[:idx]+seg2+s[idx+2500:]
# startup target hidden global
s=s.replace('''static char *initial_hover = NULL;''','''static char *initial_hover = NULL;
static bool startup_target_hidden = false;''')
# set in startup resolution immediately after char *absd = abs_path(arg);
s=s.replace('''        char *absd = abs_path(arg);
        struct stat st;''','''        char *absd = abs_path(arg);
        startup_target_hidden = base_name(absd)[0] == '.';
        struct stat st;''')
# apply after ctx_defaults for ctx0
s=s.replace('''    ctx_defaults(&ctxs[0], NULL, initpath ? initpath : ".");''','''    ctx_defaults(&ctxs[0], NULL, initpath ? initpath : ".");
    if (startup_target_hidden) ctxs[0].hidden = true;''')
open(p,'w').write(s)
PY
