{"command":"python3 - << 'PY'
p='nnn.c';s=open(p).read()
# display path simple prefix
start=s.find('static char *display_path')
end=s.find('\n/* UI state shared',start)
new='''static char *display_path(const char *path)
{
    if (!G.home) return xstrdup(path);
    size_t hl = strlen(G.home);
    if (!strncmp(path, G.home, hl)) {
        char *out = xmalloc(strlen(path) - hl + 2);
        out[0] = '~'; strcpy(out + 1, path + hl);
        return out;
    }
    return xstrdup(path);
}
'''
s=s[:start]+new+s[end:]
# ensure returns line number via global? Change signature to int (0 ok, else line)
s=s.replace('''static bool ensure_cfgdirs(void)
{
    const char *xdg = getenv("XDG_CONFIG_HOME");
    if (xdg && *xdg) {
        if (mkdir(G.cfgdir, 0755) != 0 && errno != EEXIST) return false;
    } else {
        if (mkdir_p(G.cfgdir) != 0) return false;
    }
    const char *subs[4] = { G.sessionsdir, G.bookmarksdir, G.pluginsdir, G.mountsdir };
    for (int i = 0; i < 4; i++) {
        if (mkdir(subs[i], 0755) != 0 && errno != EEXIST) return false;
    }
    return true;
}''','''static int ensure_cfgdirs(void)
{
    const char *xdg = getenv("XDG_CONFIG_HOME");
    if (xdg && *xdg) {
        if (mkdir(G.cfgdir, 0755) != 0 && errno != EEXIST) return 9392;
    } else {
        if (mkdir_p(G.cfgdir) != 0) return 9432;
    }
    const char *subs[4] = { G.sessionsdir, G.bookmarksdir, G.pluginsdir, G.mountsdir };
    for (int i = 0; i < 4; i++) {
        if (mkdir(subs[i], 0755) != 0 && errno != EEXIST) return 9392;
    }
    return 0;
}''')
s=s.replace('''    if (!ensure_cfgdirs()) { fprintf(stderr, "9392: %s\\n", strerror(errno)); return 1; }''','''    { int ecl = ensure_cfgdirs(); if (ecl) { fprintf(stderr, "%d: %s\\n", ecl, strerror(errno)); return 1; } }''')
# home handling in main
old='''    const char *home = getenv("HOME");
    if (!home || !*home) {
        struct passwd *pw = getpwuid(getuid());
        home = pw ? pw->pw_dir : "/";
    }
    G.home = xstrdup(home);'''
new='''    const char *home = getenv("HOME");
    if (!home) { fputs("set HOME\\n", stderr); return 1; }
    G.home = xstrdup(home);'''
assert old in s; s=s.replace(old,new)
# cfgbase construction for empty home gives /.config
s=s.replace('''    else { cfgbase = join_path(G.home, ".config"); }''','''    else { if (asprintf(&cfgbase, "%s/.config", G.home) < 0) cfgbase = xstrdup(".config"); }''')
open(p,'w').write(s)
